                elseif tonumber(_sw1) == 7 then
                    book = 53009
                    gem = 55710
                    room = get_room("49079")
                    place = room.name
                    hint = "off-shore of the island of great beasts."
                elseif tonumber(_sw1) == 8 then
                    book = 58415
                    gem = 55722
                    room = get_room("11820")
                    place = room.name
                    hint = "beyond the Blue-Fog Trail."
                elseif tonumber(_sw1) == 9 then
                    book = 58412
                    gem = 55741
                    room = get_room("52075")
                    place = room.name
