                local item2 = 4301
                actor:send("Give Charlemagne his dressing room key and his missing sash.")
                if (actor:get_quest_var("theatre:sash") or 0) ~= 0 or (actor:get_quest_var("theatre:charles") or 0) ~= 0 then
                    actor:send("</>")
