                if (actor:get_quest_var("theatre:charles") or 0) == 0 then
                    actor:send("%get.obj_shortdesc[%item2%]%")
                end
            elseif tonumber(_sw2) == 5 then
                actor:send("Give the Fire Goddess her skirt.")
            elseif tonumber(_sw2) == 6 then
