  -- data/triggers/023/023_14_hell_trident_speech_trident_upgrades.lua
  (23, 14, $trig$-- Speech keywords: trident upgrades
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "trident") or string.find(string.lower(speech), "upgrades")) then
    return true  -- No matching keywords
end
wait(0.2)
local hellstep = actor:get_quest_stage("hell_trident")
local level
if hellstep == 1 then
    level = 65
elseif hellstep == 2 then
    level = 90
end
if (hellstep or 0) > 0 then
    -- switch on self.id
    do
        if (self.zone_id == 23 and self.id == 11) then
            -- switch on hellstage
            local response
            do
                local _sw2 = string.lower(tostring(hellstage or ""))
                if tonumber(_sw2) == 1 then
                    response = "stage2"
                elseif tonumber(_sw2) == 2 then
                    response = "stage3"
                else
                    if actor:get_has_completed("hell_trident") then
                        response = "complete"
                    end
                end
            end
        elseif (self.zone_id == 60 and self.id == 32) then
            local step = 1
            local spell1 = actor:get_has_completed("hellfire_brimstone")
            local spell2 = actor:get_has_completed("banish")
            if not actor:get_quest_var("hell_trident:helltask6") then
                if actor:get_quest_stage("vilekka_stew") > 3 then
                    actor:set_quest_var("hell_trident", "helltask6", 1)
                end
            end
        elseif (self.zone_id == 125 and self.id == 26) then
            local step = 2
            local spell1 = actor:get_has_completed("resurrection_quest")
            local spell2 = actor:get_has_completed("hell_gate")
        end
    end
    if hellstage == "phase" then
        if not actor:get_quest_var("hell_trident:helltask5") then
            if spell1 then
                actor:set_quest_var("hell_trident", "helltask5", 1)
            end
        end
        if not actor:get_quest_var("hell_trident:helltask4") then
            if spell2 then
                actor:set_quest_var("hell_trident", "helltask4", 1)
            end
        end
    end
    local response
    if actor:get_quest_stage("hell_trident") == "step" then
        if actor.level >= level then
            if (actor:get_quest_var("hell_trident:greet") or 0) == 0 then
                actor:set_quest_var("hell_trident", "greet", 1)
                if (self.zone_id == 60 and self.id == 32) then
                    actor:send("In the hissed whisper of ecstatic fervor " .. tostring(self.name) .. " says, 'Six thrice is the number of the greater demons.  Undertaking thus six and six, and six again, their interest can be piqued.'")
                    actor:send("</>")
                    actor:send("- Attempting to land <b:yellow>six and six and six</> in thrusts of your trident shall provide the pattern of the number.")
                    actor:send("</>")
                    actor:send("- <b:yellow>Six rubies, all uncut in nature, does double the signature.")
                    actor:send("</>")
                    actor:send("- Slay <b:yellow>six beings called angels</>, be they of any make or countenance, the number being counted thrice.")
                    actor:send("</>")
                    actor:send("- Sup on the grand powers of Hell to learn the most esoteric diablery.  Complete the quests for <b:yellow>Banish</> and <b:yellow>Hellfire and Brimstone</>.")
                    actor:send("</>")
                    actor:send("- Assist the High Priestess of Lolth in hunting down and destroying the heretics of her Goddess.")
                    wait(2)
                    actor:send(tostring(self.name) .. " says, 'In undertaking six in all will Hell be at your beck and call.'")
                elseif (self.zone_id == 125 and self.id == 26) then
                    actor:send(tostring(self.name) .. " says, 'Perhaps I will grant you a boon if you carry out sacrifices in my name.'")
                    actor:send("</>")
                    actor:send("- <b:yellow>Attack with " .. tostring(objects.template(23, 39).name) .. " 666 times</> as a sacrifice of power.")
                    actor:send("</>")
                    actor:send("- Bring me <b:yellow>six radiant rubies</> as a sacrifice of wealth.")
                    actor:send("</>")
                    actor:send("- Slay a combination of <b:yellow>six ghaeles, solars, or lesser seraphs</>.  Their suffering shall please me as a sacrifice of divinity.")
                    actor:send("</>")
                    actor:send("- Learn the most unholy of prayers.  Complete the quests for <b:yellow>Resurrection</> and <b:yellow>Hell Gate</> as a sacrifice of knowledge.")
                    actor:send("</>")
                    actor:send("- Finally, find one long-buried and branded an infidel.  <b:yellow>Finish his undying duel for him</> as a sacrifice of honor.")
                    wait(2)
                    actor:send(tostring(self.name) .. " says, 'Do this and I will lend you a greater share of my power.'")
                end
                wait(2)
                actor:send(tostring(self.name) .. " says, 'You can ask about your <b:cyan>[weapon progress]</> at any time.'")
            else
                actor:send(tostring(self.name) .. " says, 'Remember your six sacrifices.  Ask about your <b:cyan>[weapon progress]</> if you must.'")
            end
        else
            response = "level"
        end
    else
        if actor:get_has_completed("hell_trident") then
            response = "complete"
        elseif actor:get_quest_stage("hell_trident") < step then
            response = "stage1"
        else
            response = "stage3"
        end
    end
    if response == "stage1" then
        actor:send(tostring(self.name) .. " says, 'You must make the initial offerings with another dark priest.'")
    elseif response == "stage2" then
        if actor.level >= level then
            actor:send(tostring(self.name) .. " says, 'Hell hungers for more and will reward you greatly if you feed it.  Attack with that trident 666 times then seek out the Black Priestess, the left hand of Ruin Wormheart.  She will guide your offerings.'")
        else
            actor:send(tostring(self.name) .. " says, 'Other forces of Hell will eventually take notice of you too now.  Seek out the left hand of Ruin Wormheart, the Black Priestess, after you have grown more.  She will be your emissary.'")
            actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
        end
    elseif response == "stage3" then
        if actor.level >= level then
            actor:send(tostring(self.name) .. " says, 'The Demon Lord Krisenna is known to traffic with mortals from time to time.  Impress him and perhaps he will grant you a boon.'")
        else
            actor:send(tostring(self.name) .. " says, 'Continue to prove your value to Hell and perhaps a Demon Lord might be willing to grant your their patronage.'")
            actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
        end
    elseif response == "complete" then
        actor:send(tostring(self.name) .. " says, 'You've already marshalled the forces of Hell and Damnation to your side!'")
    elseif response == "level" then
        actor:send(tostring(self.name) .. " say, 'Stand before me again when you have achieved a larger measure of greatness.'")
        actor:send("<red>You must be level " .. tostring(level) .. " or greater to continue this quest.</>")
    end
end$trig$, 'fb16a8d427a6bf59d234069f2ac0fa4b'),
  -- data/triggers/028/028_00_waterform_wave_greet.lua
  (28, 0, $trig$wait(0.2)
if not actor.is_player then
    return true
end
local stage = actor:get_quest_stage("waterform")
if stage == 0 then
    if actor.class and string.find(actor.class, "cryomancer") then
        self:say("How nice to see someone other than those dreadful pirates.")
        if actor.level > 72 then
            wait(2)
            self.room:send(tostring(self.name) .. " says, 'Oh, and such a capable water master too.  I could offer")
            self.room:send("</>you a modicum of protection against those pirates if you like.  Would you be")
            self.room:send("</>interested?'")
        end
    end
elseif stage == 1 then
    self:say("Did you find a piece of armor made of water?")
elseif stage == 2 then
    self:say("You should be out killing Tri-Aszp.")
elseif stage == 3 then
    self:say("Have you found a suitably large white dragon bone?")
elseif stage == 4 or stage == 5 then
    self:say("Ah, how are your water creature sample studies going?")
elseif stage == 6 then
    self:say("Do you need to confer about your notes on water sources?")
elseif stage == 7 then
    self:command("peer " .. tostring(actor))
    wait(1)
    self.room:send(tostring(self.name) .. " says, 'Ah I can see you have gleaned secrets from the waters!")
    self.room:send("</>Give me the dragon bone cup when you're ready.'")
end$trig$, '4bde02fd9684fcab427f63c44cc1e7d0'),
  -- data/triggers/028/028_01_waterform_wave_speech1.lua
  (28, 1, $trig$-- Speech keywords: yes / protection / how / okay
-- DG word list (num_arg 1): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"yes", "protection?", "how?", "okay"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end
local speech_lower = string.lower(speech)
local speech_lower = string.lower(speech or "")
if not (string.find(speech_lower, "yes") or string.find(speech_lower, "protection")
        or string.find(speech_lower, "how") or string.find(speech_lower, "okay")) then
    return true
end
wait(0.2)
local stage = actor:get_quest_stage("waterform")
if stage == 0 and actor.is_player and actor.class
        and string.find(actor.class, "cryomancer") and actor.level > 72 then
    actor:start_quest("waterform")
    self.room:send(tostring(self.name) .. " says, 'I can teach you to transform you into a raging torrent,")
    self.room:send("</>giving you the strength of the water itself!  All you need is a single piece of")
    self.room:send("</>armor made from water to wrap about you.'")
    -- 
    -- THIS. IS. A. LIE.  Yes, the quest master, a talking wave, gets the material components of its own spell wrong.
    -- 
    wait(4)
    self:say("Bring it to me and I will teach you the transformation!")
    wait(2)
    self.room:send(tostring(self.name) .. " says, 'If you forget, you can ask me for a reminder of your")
    self.room:send("</><b:white>[progress]</>.'")
elseif stage == 1 then
    self:say("Then please give it to me.")
elseif stage == 2 or stage == 3 then
    self:say("Then please give it to me.")
elseif stage == 4 then
    self:say("Splendid!  Please, keep at it!")
elseif stage == 5 then
    self:say("Splendid!  Give me the bone cup if you're done.")
elseif stage == 6 then
    self.room:send(tostring(self.name) .. " says, 'If you need, you may ask for a reminder of your")
    self.room:send("</><b:white>[progress]</>.'")
end$trig$, 'ca7e5264424f3f4b246f5ec937f0f3a5'),
  -- data/triggers/028/028_02_waterform_wave_receive.lua
  (28, 2, $trig$local stage = actor:get_quest_stage("waterform")
if actor:get_quest_var("waterform:new") == "yes" then
    if object.zone_id == 28 and object.local_id == 7 then
        wait(0.2)
        self:say("Yes, I can make a new dragon bone cup from this.")
        world.destroy(object)
        actor:set_quest_var("waterform", "new", 0)
        wait(2)
        self.room:send(tostring(self.name) .. " transforms into a torrential swirling column!")
        self.room:send("The riptide whittles away at the ice white bone, carving it into a smooth cup.")
        self.room:send(tostring(self.name) .. " slowly resumes into its gentle undulating form, the cup floating on its crest.")
        self.room:spawn_object(28, 8)
        wait(2)
        self:command("give dragon-bone-cup " .. tostring(actor.name))
        self:say("Don't lose this again!")
    else
        wait(0.2)
        self:say("I can't make a new cup from this.")
        self.room:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
    end
elseif stage == 1 then
    if object.zone_id == 510 and object.local_id == 9 then
        actor:advance_quest("waterform")
        wait(0.2)
        self:destroy_item("shield")
        self:say("Yes, this will do nicely.")
        self.room:send(tostring(self.name) .. " absorbs " .. tostring(objects.template(510, 9).name) .. " into its massive form!")
        wait(2)
        self:say("Now hold still.")
        wait(2)
        self.room:send(tostring(self.name) .. " crests up to a monumental height and pauses for just a moment.")
        wait(4)
        actor:send(tostring(self.name) .. " CRASHES down and engulfs you!")
        self.room:send_except(actor, tostring(self.name) .. " CRASHES down and engulfs " .. tostring(actor.name) .. "!")
        wait(4)
        actor:send("You feel your body start to soften and flow!")
        actor:send("You feel at one with the Great Wave!")
        self.room:send_except(actor, tostring(actor.name) .. " to merges with the Great Wave!")
        wait(6)
        actor:send("Suddenly you feel your body solidify again.")
        actor:send("You begin to choke!")
        self.room:send_except(actor, tostring(actor.name) .. " begins to struggle against the torrent!")
        wait(5)
        self.room:send_except(actor, tostring(self.name) .. " recedes leaving " .. tostring(actor.name) .. " heaving for breath.")
        actor:send(tostring(self.name) .. " recedes, leaving you gasping for air.")
        wait(5)
