  -- data/triggers/030/030_96_druid_moonwell_clue_answer.lua
  (30, 96, $trig$-- Converted from DG Script #3096: druid_moonwell_clue_answer
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: punished
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "punished")) then
    return true  -- No matching keywords
end
if actor.class == "druid" then
    if actor.level >= 73 then
        wait(1.5)
        self:say("Yes, yes, but hopefully one day she'll be able to leave that tree.")
        wait(1.5)
    else
        wait(1.5)
        self:say("I'm sorry, but you are still too young.")
        wait(0.5)
        self:command("smile " .. tostring(actor.name))
        self:command("ruffle " .. tostring(actor.name))
    end
else
    self:say("I'm sorry, but it's okay.  Don't worry about it.")
    self:command("smile " .. tostring(actor.name))
end$trig$, '78b9763b42d65d96aae59f52e94df5e0'),
  -- data/triggers/040/040_13_borgan_attack.lua
  (40, 13, $trig$if not percent_chance(20) then
    return true
end

local val = random(1, 10)
do
    local _sw1 = string.lower(tostring(val or ""))
    if tonumber(_sw1) == 1 then
        self:breath_attack("fire", nil)
    elseif tonumber(_sw1) == 2 or tonumber(_sw1) == 3 then
        self:command("sweep")
    elseif tonumber(_sw1) == 4 or tonumber(_sw1) == 5 then
        self:command("roar")
    else
        self:command("growl")
    end
end$trig$, '28991771581f6bebcfd59f087102623e'),
