    self:command("ponder")
    wait(2)
    local part = actor:get_quest_var("pyromancer_subclass:part")
    local place
    if part == "white" then
        place = "&bin some kind of mine&0"
    elseif part == "black" then
        place = "&bin some kind of temple&0"
    elseif part == "gray" then
        place = "&bnear some kind of hill&0"
