-- `%type%_wand` percent-substituted quest names; none of those exist in
-- the Lua runtime. Re-introduce after the type_wand quest is redesigned.
return true$trig$, '1cfdc706b06c46bd0b96d2cea10731f8'),
  -- data/triggers/052/052_16_emmath_receive_decline.lua
  (52, 16, $trig$-- DG receive trigger, num_arg 0: the arg list (5211 5212 17308 23822 318) holds the items
-- other triggers handle; this one runs for every other item. The runtime does not filter on
-- arg_list, so the exclusion lives here. (The converter's percent_chance(0) guard blocked it all.)
if (object.zone_id == 52 and object.id == 11)
    or (object.zone_id == 52 and object.id == 12)
    or (object.zone_id == 173 and object.id == 8)
    or (object.zone_id == 238 and object.id == 22)
    or (object.zone_id == 2 and object.id == 118) then
    return true
end

local stage_subclass = actor:get_quest_stage("pyromancer_subclass") or 0
local response
if stage_subclass > 0 and stage_subclass <= 4 then
    response = "I asked you to bring me the " .. tostring(actor:get_quest_var("pyromancer_subclass:part")) .. " flame, not this nonsense."
elseif actor:get_quest_stage("type_wand") > 0 then
    response = "I can't craft with this!"
elseif (actor:get_quest_stage("emmath_flameball") or 0) > 1 then
    response = "You're supposed to be out collecting flames, not whatever this is."
else
    response = "Why are you bringing me this trash?"
end

self.room:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
wait(0.2)
actor:send(tostring(self.name) .. " says, '" .. tostring(response) .. "'")
return true$trig$, 'bba6142d219bc696c76157c05d31902f'),
  -- data/triggers/052/052_78_lava_death_trig.lua
  (52, 78, $trig$wait(0.2)
while self.actor_count > 0 do
    local dice1 = random(1, 60)
    local dice2 = random(1, 60)
    local damage = dice1 + dice2
    local victim = self.room.actors[random(1, #self.room.actors)]
    if victim then
        local damage_dealt = victim:damage(damage)  -- type: fire
        if damage_dealt == 0 then
            self.room:send_except(victim, "A large lava bubble bursts near " .. tostring(victim.name) .. ", but " .. tostring(victim.possessive) .. " body absorbs the blast!")
            victim:send("A large lava bubble bursts right next to you.  Luckily, you are well-protected.")
        else
            self.room:send_except(victim, "A large lava bubble bursts near " .. tostring(victim.name) .. ", burning " .. tostring(victim.object) .. "! (<red>" .. tostring(damage_dealt) .. "</>)")
            victim:send("A large lava bubble bursts right next to you - OUCH, that burns! (<red>" .. tostring(damage_dealt) .. "</>)")
        end
        if victim:get_quest_stage("meteorswarm") == 3 and victim:get_quest_var("meteorswarm:fire") == 1 then
            victim:advance_quest("meteorswarm")
            wait(1)
            victim:send("<red>You feel your mastery over fire growing!</>")
        end
    else
        return true
    end
    wait(2)
end$trig$, '9b1443032f4e7a13e81af4ff706bcc93'),
