    mob1 = 52003
    mob2 = 52015
    item = objects.template(520, 1).name
elseif stage == 11 then
    item = objects.template(520, 1).name
else
    self:say("Did you want to do a quest of some kind?  Because you're not at the moment.  Get lost.")
