  -- data/triggers/123/123_14_megalith_quest_keeper_speech.lua
  (123, 14, $trig$-- Converted from DG Script #12314: megalith_quest_keeper_speech
-- Original: MOB trigger, flags: SPEECH, SPEECH_TO, num_arg: 1 (DG word-list mode, not a probability)

-- DG word list (num_arg 1): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"yes", "sure", "no", "i"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end
wait(0.2)
if actor:get_quest_stage("megalith_quest") == 2 then
    if speech == "yes" or speech == "sure" or string.find(speech, "I will") or string.find(speech, "I can") then
        -- switch on self.id
        -- 
        -- North - get ring from Tech
        -- 
        if actor:get_quest_var("megalith_quest:north") == 0 then
            if (self.zone_id == 123 and self.id == 3) then
                self:say("Thank you very kindly.")
                wait(0.5)
                self.room:send(tostring(self.name) .. " says, 'Far to the north, there is a civilization dedicated to the Great Snow Leopard.  There, they make <green>rings of simple granite</> which grant their constructs powerful mystic protection.  Such energies should make an ideal offering to the Earth Spirits.  Please retrieve one for me.'")
                wait(6)
                self.room:send(tostring(self.name) .. " says, 'Remember, we must call the elements in order:")
                self.room:send("</><b:yellow>East</>, <red>South</>, <b:cyan>West</>, <b:green>North</>")
                self.room:send("</>so please start with <b:yellow>" .. tostring(mobiles.template(123, 5).name) .. "</>.'")
                self:command("bow " .. tostring(actor.name))
                actor:set_quest_var("megalith_quest", "north", 1)
                return _return_value
            end
            -- 
            -- South - Fiery Eye from Vulcera
            -- 
            if actor:get_quest_var("megalith_quest:south") == 0 then
            elseif (self.zone_id == 123 and self.id == 4) then
                self:say("Excellent.")
                wait(0.4)
                self.room:send(tostring(self.name) .. " says, 'There is an island in the sea where fires of the deep meet the outer world, ruled by a demigoddess.  My people know her magic to be the ultimate blending of divine spark and protean fire.  She carries <b:red>a jewel that burns with that same fire</>.  If you can retrieve it, I believe that would be the perfect offering to the Spirits of Fire.'")
                actor:set_quest_var("megalith_quest", "south", 1)
                wait(4)
                self.room:send(tostring(self.name) .. " says, 'Remember, we must call the elements in order:")
                self.room:send("</><b:yellow>East</>, <red>South</>, <b:cyan>West</>, <b:green>North</>")
                self.room:send("</>So please start with <b:yellow>" .. tostring(mobiles.template(123, 5).name) .. "</>.'")
                wait(2)
                self:command("nod " .. tostring(actor.name))
                self:say("Good hunting.")
                return _return_value
            end
            -- 
            -- East - cumulus bracelet
            -- 
            if actor:get_quest_var("megalith_quest:east") == 0 then
            elseif (self.zone_id == 123 and self.id == 5) then
                self:say("Hurray!")
                self:command("clap")
                wait(1)
                self:say("There are a handful of places in the world where the clouds reach from the ground to the heavens.  One such place is the home to an ancient silver dragon.")
                wait(1)
                self:command("laugh")
                self:say("Don't worry, you don't need to mess with him on my behalf.")
                wait(2)
                self:say("His guardians on the other hand...")
                self:command("grin")
                wait(4)
                self.room:send(tostring(self.name) .. " says, 'Some carry <b:white>cumulus cloud bracelets</>.  If you can get your hands on one, it'll boost my call to the Air Spirits right through the stratosphere!'")
                wait(6)
                self.room:send(tostring(self.name) .. " says, 'Remember, we have to cast in order:")
                self.room:send("</></><b:yellow>East</>, <red>South</>, <b:cyan>West</>, <b:green>North</>")
                self.room:send("</>So when you return the offerings, please start with <b:yellow>me</>!'")
                actor:set_quest_var("megalith_quest", "east", 1)
                wait(5)
                self:say("Why are you still standing here?!")
                wait(0.2)
                self:say("Go!  Go!")
                return _return_value
            end
            -- 
            -- West - Spring Water
            -- 
            if actor:get_quest_var("megalith_quest:west") == 0 then
            elseif (self.zone_id == 123 and self.id == 6) then
                self:say("Wonderful!")
                wait(2)
                self:say("As a creature of the Dreaming, my magic is especially fueled by energies that thin the veil between the worlds.")
                wait(3)
                self.room:send(tostring(self.name) .. " says, 'My faerie sisters have told me there is a <b:cyan>hidden spring in the surrounding forest</>.  Over the ages, it has absorbed the gentle radiance of the moon, making it ideally sympathetic with the power of the Reverie.  Even the waters from my home in the Kingdom of Dreams would pale in comparison!'")
                wait(6)
                self.room:send(tostring(self.name) .. " says, 'Please, take the cup you gave to the priestess, <b:cyan>fill it with water from that spring</>, and bring it back with water for me to offer the Spirits of the West.'")
                wait(6)
                self:command("ponder")
                self:say("Although this spring sounds ideal, I suppose any water will do.")
                actor:set_quest_var("megalith_quest", "west", 1)
                wait(3)
                self.room:send(tostring(self.name) .. " says, 'Remember, we must call the elements in order:")
                self.room:send("</><b:yellow>East</>, <red>South</>, <b:cyan>West</>, <b:green>North</>")
                self.room:send("</>So please start with <b:yellow>" .. tostring(mobiles.template(123, 5).name) .. "</>.'")
                self:command("curtsy " .. tostring(actor.name))
                return _return_value
            end
        end
    elseif speech == "no" then
        wait(0.2)
        self:command("shrug")
        self:say("Alright then.")
    end
end$trig$, '0961b2b457c79b40b89d7bf22a38cf37'),
  -- data/triggers/123/123_15_megalith_quest_keeper_receive.lua
  (123, 15, $trig$-- Converted from DG Script #12315: megalith_quest_keeper_receive
-- Original: MOB trigger, flags: RECEIVE, probability: 100%
local _return_value = true  -- Default: allow action
-- This trigger is used to collect all the items for stage 2.
--
-- TODO(parity): self.id checks use legacy 5-digit vnums (12303..12306).
-- Once split, swap to self.local_id (3..6 in zone 123). Same for the
-- vessel checks (41110, 41111, 18512) and per-Keeper "need" object IDs
-- (55020, 48109, 8301).

local item = object.id
local me = self.id

-- Hoisted from branch-scoped locals in the converter output.
local direction
local part
local nxt
local need

if (self.zone_id == 123 and self.id == 3) then
    -- North, Earth - Granite Ring from Tech
    direction = "north"
    part = 4
    nxt = 12301
    need = 55020
elseif (self.zone_id == 123 and self.id == 4) then
    -- South, Fire - Fiery Eye from Fiery Island
    direction = "south"
    part = 2
    nxt = 12306
    need = 48109
elseif (self.zone_id == 123 and self.id == 5) then
    -- East, Air - cumulus bracelet from Dargentan
    direction = "east"
    part = 1
    nxt = 12304
    need = 8301
elseif (self.zone_id == 123 and self.id == 6) then
    -- West, Water - water from the hidden spring, or not - BAD STUFF
    -- This Keeper's request is the one to watch out for.
    direction = "west"
    part = 3
    nxt = 12303
    need = actor:get_quest_var("megalith_quest:goblet")
end

if actor:get_quest_stage("megalith_quest") == 2 then
    if (item == need) or ((self.zone_id == 123 and me == 6) and ((object.zone_id == 411 and item == 10) or (object.zone_id == 411 and item == 11) or (object.zone_id == 185 and item == 12))) then
        -- Already given, right item.
        local part_key = "item" .. tostring(part)
        if actor:get_quest_var("megalith_quest:" .. part_key) == 1 then
            self:command("shake")
            self:say("You've already given me this.")
            return _return_value
        elseif actor:get_quest_var("megalith_quest:" .. direction) == 1 then
            -- Right item, wrong order.
            if part > 1 then
                local check = part - 1
                local check_key = "item" .. tostring(check)
                if actor:get_quest_var("megalith_quest:" .. check_key) == 0 then
                    self:command("shake")
                    self.room:send(tostring(self.name) .. " says, 'We must cast the circle in order:")
                    self.room:send("East, South, West, North.")
                    self.room:send("Please deliver your offerings in that order.'")
                    return _return_value
                end
            end
            -- Right set, wrong specific vessel at West.
            if (self.zone_id == 123 and me == 6) and ((item ~= need) or (object.val2 ~= 0)) then
                self:command("shake")
                self:say("I need water returned in the cup " .. tostring(mobiles.template(123, 1).name) .. " has consecrated.")
                return _return_value
            else
                wait(0.2)
                actor:set_quest_var("megalith_quest", direction, 0)
                actor:set_quest_var("megalith_quest", part_key, 1)
                if direction == "north" then
                    self:say("Ah, excellent!  This will make a perfect offering.")
                    wait(0.6)
                    self.room:send(tostring(self.name) .. " places " .. tostring(object.shortdesc) .. " before the menhir and kneels.")
                    wait(2)
                    self.room:send(tostring(self.name) .. " chants:")
                    self.room:send("'Hail to the guardian Spirits of the North")
                    self.room:send("</>Spirits of Earth and Determination")
                elseif direction == "south" then
                    self:say("Marvelous!  This will make a perfect offering.")
                    wait(0.6)
                    self.room:send(tostring(self.name) .. " raises " .. tostring(object.shortdesc) .. " above her head.")
                    wait(2)
                    self.room:send(tostring(self.name) .. " chants:")
                    self.room:send("'Hail to the guardian Spirits of the South")
                    self.room:send("</>Spirits of Fire and Feeling")
                elseif direction == "east" then
                    self:say("Great!  This will make a perfect offering.")
                    wait(0.6)
                    self.room:send(tostring(self.name) .. " shakes out " .. tostring(object.shortdesc) .. " like a blanket.")
                    self.room:send("She watches with delight as it dissolves into wisps of cloudy mist.")
                    wait(4)
                    self.room:send(tostring(self.name) .. " chants:")
                    self.room:send("'Hail to the guardian Spirits of the East")
                    self.room:send("</>Spirits of Air and Intellect")
                elseif direction == "west" then
                    if actor:get_quest_var("megalith_quest:item5") == 1 then
                        self:say("Ah, delightful!  This water will make a perfect offering.")
                        wait(0.6)
                    else
                        self:say("This will do.")
                        actor:set_quest_var("megalith_quest", "bad2", 1)
                        wait(0.6)
                    end
                    self.room:send(tostring(self.name) .. " pours the water from " .. tostring(object.shortdesc) .. " before the menhir.")
                    wait(2)
                    self.room:send(tostring(self.name) .. " chants:")
                    self.room:send("'Hail to the guardian Spirits of the West")
                    self.room:send("</>Spirits of Water and Intuition")
                end
                self.room:send("</>I present this offering to you.")
                self.room:send("</>Aid us in our magical working on this great day.'")
                wait(5)
                world.destroy(object)
                self.room:send("The menhir begins to hum and glow!")
                wait(3)
                -- Next person.
                if (actor:get_quest_var("megalith_quest:item1") == 1) and (actor:get_quest_var("megalith_quest:item2") == 1) and (actor:get_quest_var("megalith_quest:item3") == 1) and (actor:get_quest_var("megalith_quest:item4") == 1) then
                    self:say("Now, return to " .. tostring(mobiles.template(123, 1).name) .. " at the altar and help her finish the call!")
                else
                    -- TODO(parity): nxt is still a legacy 5-digit vnum.
                    -- Translate to (zone, local_id) for catalog lookup.
                    local nxt_zone = math.floor(nxt / 100)
                    local nxt_id = nxt % 100
                    local nxt_template = mobiles.template(nxt_zone, nxt_id)
                    local nxt_name = nxt_template and nxt_template.name or ("the next Keeper")
                    self:say("Now, proceed to " .. tostring(nxt_name) .. " and continue invoking the elements.")
                end
            end
        end
    end
end
return _return_value$trig$, 'e3c1e78b5f035014e8b941a5a8e799fa'),
  -- data/triggers/123/123_16_megalith_quest_act_fill.lua
  (123, 16, $trig$-- Converted from DG Script #12316: megalith_quest_act_fill
-- Original: OBJECT trigger, flags: COMMAND, probability: 3%

-- Command location mask 3: legacy OCMD_EQUIP=1 (worn), OCMD_INVEN=2 (carried), OCMD_ROOM=4 (floor)
if not (location == "equip" or location == "inventory") then
    return true  -- Not in a location this trigger watches
end

-- Command filter: fill
if not (cmd == "fill") then
    return true  -- Not our command
end
local _return_value = false  -- Default: block the command (legacy script_driver ret_val = 1)
-- Questor should fill a vessel from room 12401
-- Doing so will set item5 if the questor is on stage 2
-- 
-- switch on cmd
do
    local _sw1 = string.lower(tostring(cmd or ""))
    if _sw1 == "f" or _sw1 == "fi" then
        _return_value = true
        return _return_value
    end
end
