                person:set_quest_var("desert_quest", "lever", 1)
            end
        end
    else
        if actor:get_quest_stage("desert_quest") == 0 then
            actor:start_quest("desert_quest")
        end
        actor:set_quest_var("desert_quest", "lever", 1)
    end
end$trig$, 'd0a812110e05ee4e4279eaac1c6eb205'),
