  -- data/triggers/163/163_10_eleweiss_refuse.lua
  (163, 10, $trig$-- TODO(parity): the original gated on `object.id == %wandgem% || %wand_id%`
-- where wandgem and wand_id were DG globals naming the in-progress wand parts.
-- The Lua runtime doesn't yet expose those identifiers, so the gate is a stub
-- that always falls through to the refusal path. Wire the wand quest schema
-- through before re-enabling.

wait(0.2)
actor:send(tostring(self.name) .. " says, 'What is this?'")
wait(0.3)
actor:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
wait(0.2)
actor:send(tostring(self.name) .. " says, 'I have no need of " .. tostring(object.shortdesc) .. ".'")
return true$trig$, '37c34d70ebc201e256631d936bc2cfd9'),
  -- data/triggers/163/163_39_dryad_moonwell_greet.lua
  (163, 39, $trig$if actor.class ~= "druid" then
    return true
end

if actor.level < 73 then
    wait(0.5)
    actor:send(tostring(self.name) .. " looks you over and says, 'It is good to see a druid again, but you\n"
        .. "</>have not yet seen enough of the world to help me.  Please come back when you\n"
        .. "</>are more experienced.'")
    self.room:send_except(actor, tostring(self.name) .. " tells " .. tostring(actor.name) .. " something.")
    return true
end

local stage = actor:get_quest_stage("moonwell_spell_quest")
if stage == 1 or stage == 2 then
    wait(0.5)
    if actor.gender == "male" then
        actor:send(tostring(self.name) .. " tells you, 'Welcome back Brother.'")
    elseif actor.gender == "female" then
        actor:send(tostring(self.name) .. " tells you, 'Welcome back Sister.'")
    end
    wait(1)
    actor:send(tostring(self.name) .. " tells you, 'Have you recovered the Vine of Mielikki?!  Please give it\n"
        .. "</>to me.'")
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
elseif stage == 3 then
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Do you have the stone?  Please, give it to me!'")
    self:command("smile " .. tostring(actor.name))
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
elseif stage == 4 or stage == 5 then
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Do you have the flask?  Please give it to me if you do!'")
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
elseif stage == 6 then
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Did you get the stone of power?  Please give it to me!'")
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
elseif stage == 7 then
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Do you have the orb from the dark fortress?  Please give\n"
        .. "</>me the orb.'")
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
elseif stage == 8 or stage == 9 then
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'The second stone of power, you have it?  Please give it\n"
        .. "</>to me, we are almost complete!'")
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
elseif stage == 10 then
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'The orb to balance the ritual, do you have it?  Please\n"
        .. "</>give me the orb!'")
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
elseif stage == 11 or stage == 12 then
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'The last stone of power, do you have it?  Please give me\n"
        .. "</>the last relic and we are finished!'")
    self.room:send_except(actor, tostring(self.name) .. " asks " .. tostring(actor.name) .. " something.")
else
    wait(0.5)
    self.room:send(tostring(self.name) .. " weeps lightly.")
    wait(1)
    self.room:send_except(actor, tostring(self.name) .. " takes notice of " .. tostring(actor.name) .. " and quickly wipes her tears.")
    actor:send(tostring(self.name) .. " takes notice of you and quickly wipes her tears.")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Hello fellow of the Order.'")
    self.room:send_except(actor, tostring(self.name) .. " tells something to " .. tostring(actor.name) .. ".")
    wait(1)
    actor:send(tostring(self.name) .. " tells you, 'It is good to see a promising druid again.'")
    self.room:send(tostring(self.name) .. " smiles through her tears.")
end$trig$, '820c2b48570c9fe821ca19f3f892c8e2'),
  -- data/triggers/163/163_41_dryad_moonwell_again.lua
  (163, 41, $trig$local sl = string.lower(speech)
if not (string.find(sl, "druid?") or string.find(sl, "promising?") or string.find(sl, "again?")) then
    return true
end

if actor.class ~= "druid" or actor.level < 73 then
    return true
end

globals.moon_name = actor.name

wait(0.5)
self:command("sigh")
wait(1)
actor:send(tostring(self.name) .. " tells you, 'Yes, well...'")
self.room:send_except(actor, tostring(self.name) .. " tells something to " .. tostring(actor.name) .. ".")
wait(0.5)
self.room:send(tostring(self.name) .. " starts to reminisce about her past.")
wait(0.5)
actor:send(tostring(self.name) .. " tells you, 'You see, I was not always like this.  Many years ago I\n"
    .. "</>too was a young mortal druid.  But while on my journeys I made a grave error in\n"
    .. "</>judgement.'")
wait(3)
actor:send(tostring(self.name) .. " tells you, 'I rediscovered powerful magics that allowed me to travel\n"
    .. "</>the world on a whim.'")
wait(3)
actor:send(tostring(self.name) .. " tells you, 'But I squandered that magic on frivolous desires and\n"
    .. "</>furthering my own ambitions, rather than using it to better perform my sworn\n"
    .. "</>duties.'")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Thus the great goddess Mielikki punished me by binding me\n"
    .. "</>to this tree as a dryad so I might never travel again.'")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Now, if I do not perform my duties properly, I ensure my\n"
    .. "</>own death.'")
self.room:send_except(actor, tostring(self.name) .. " tells her story to " .. tostring(actor.name) .. ".")
wait(7)
self:command("sigh")
wait(0.5)
self:command("ponder")
wait(0.5)
actor:send(tostring(self.name) .. " tells you, 'But perhaps if I repent by teaching you these ancient\n"
    .. "</>magics, the goddess will release me from this place!'")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Yes, if you are willing I will teach you the power of\n"
    .. "</>druidic travel.'")
self.room:send_except(actor, tostring(self.name) .. " seems excited while telling something to " .. tostring(actor.name) .. ".")
wait(4)
actor:send(tostring(self.name) .. " tells you, 'Are you willing to learn?'")$trig$, 'a983783b1764ae16147252228b0e8143'),
  -- data/triggers/163/163_42_dryad_moonwell_yesno.lua
  (163, 42, $trig$local sl = string.lower(speech)
if not (string.find(sl, "yes") or string.find(sl, "no")) then
    return true
end

if actor.name ~= globals.moon_name then
    return true
end

globals.moon_name = nil

if string.find(sl, "no") then
    self:command("frown")
    actor:send(tostring(self.name) .. " tells you, 'Very well, that is your choice.'")
    self.room:send_except(actor, tostring(self.name) .. " seems disappointed as she says something to " .. tostring(actor.name) .. ".")
    return true
end

if string.find(sl, "yes") then
    self.room:send(tostring(self.name) .. " smiles with a slight twinkle in her eye.")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Very well, I will teach you what I know.'")
    self.room:send_except(actor, tostring(self.name) .. " seems pleased as she speaks with " .. tostring(actor.name) .. ".")
    wait(2)
    actor:send(tostring(self.name) .. " tells you 'I will guide you through the proper performance of a\n"
        .. "</>complex ceremony to create a well of moonlight.'")
    wait(4)
    actor:send(tostring(self.name) .. " tells you, 'This ceremony requires several powerful symbols and\n"
        .. "</>materials.  You must attain these materials since I cannot leave this place.'")
    self.room:send_except(actor, tostring(self.name) .. " excitedly tells " .. tostring(actor.name) .. " something.")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'First we need something to mark the well's outline.'")
    self.room:send_except(actor, tostring(self.name) .. " begins telling something to " .. tostring(actor.name) .. ".")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Long ago during the Rift Wars, the goddess Mielikki was\n"
        .. "</>injured by another god, and one of the vines that surround her body was cut\n"
        .. "</>off.  As this was more than a mere plant but rather part of Her divine body, it\n"
        .. "</>survived.'")
    wait(6)
    actor:send(tostring(self.name) .. " tells you, 'I have heard tell this vine has proliferated near molten\n"
        .. "</>mountains, but is guarded by fearsome fiery beasts.'")
    wait(4)
    actor:send(tostring(self.name) .. " tells you, 'Go, recover part of this vine and bring it back safely!'")
    self.room:send_except(actor, tostring(self.name) .. " pleads with " .. tostring(actor.name) .. " desperately.")
    actor:start_quest("moonwell_spell_quest")
end$trig$, '05115ad4c9281504fe50be7fdac3571b'),
  -- data/triggers/163/163_49_moonwell_vine_receive.lua
  (163, 49, $trig$if actor:get_quest_stage("moonwell_spell_quest") == 1 then
    wait(0.2)
    self:destroy_item("vine")
    actor:send(tostring(self.name) .. " tells you, 'How did you get this?  No, go get it yourself.'")
elseif actor:get_quest_stage("moonwell_spell_quest") == 2 then
    wait(0.2)
    self:destroy_item("vine")
    actor:advance_quest("moonwell_spell_quest")
    actor:send(tostring(self.name) .. " tells you, 'Very good.  I can now lay out the well's boundaries.'")
    wait(1)
    self.room:send(tostring(self.name) .. " places the vine in a small circle on the ground.")
    self:command("smile " .. tostring(actor.name))
    wait(1)
    actor:send(tostring(self.name) .. " tells you, 'Excellent.  Now we must have stone.  Of course there is")
    actor:send("</>plenty of stone here, but we need to have a stone with significant energy to")
    actor:send("</>act as a magical anchor point.'")
    wait(1.5)
    actor:send(tostring(self.name) .. " tells you, 'Far to the north there is an ancient burial site.  Within")
    actor:send("</>its catacombs lays a stone of great power, shaped like a heart.  Obtain this")
    actor:send("</>stone and it will surely increase our well's power.'")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Go now while I continue construction of our well.'")
    wait(2)
    self.room:send(tostring(self.name) .. " begins to collect some rocks and place them around the vine circle.")
end$trig$, '02f16b8843e47d7e93bff30cba3eb91c'),
  -- data/triggers/163/163_50_moonwell_quest_status_checker.lua
  (163, 50, $trig$local sl = string.lower(speech)
if not (string.find(sl, "status") or string.find(sl, "progress")) then
    return true
end

wait(0.2)

if actor:get_has_completed("moonwell_spell_quest") then
    self:say("I have already taught you to travel through moonwells.")
    return true
end

local stage = actor:get_quest_stage("moonwell_spell_quest")
local item, place

if stage == 1 or stage == 2 then
    item = {163, 50}  -- Vine of Mielikki (16350)
    place = "an island of lava and fire."
elseif stage == 3 then
    item = {480, 24}  -- The Heartstone (48024)
    place = "an ancient burial site far to the north"
elseif stage == 4 or stage == 5 then
    item = {163, 56}  -- Flask of Eleweiss (16356)
    place = "the cult of the ice dragon"
elseif stage == 6 then
    item = {52, 1}  -- Glittering ruby ring (5201)
    place = "a temple dedicated to fire"
elseif stage == 7 then
    item = {160, 6}  -- Orb of Winds (16006)
    place = "a dark fortress to the east"
elseif stage == 8 then
    self:say("Please give me your map to update.")
    return true
elseif stage == 9 then
    item = {490, 11}  -- Jade ring (49011)
    place = "a wood nymph on an island of our brothers beset by beasts"
elseif stage == 10 then
    item = {40, 3}  -- Chaos Orb (4003)
    place = "a great dragon hidden in a hellish labyrinth"
elseif stage == 11 then
    item = {550, 20}  -- Granite Ring (55020)
    place = "a large temple hidden in a mountain"
elseif stage == 12 then
    self:say("Please give me your map to make the final markings.")
    return true
else
    self:say("You haven't agreed to help me yet.")
    return true
end

local item_name = objects.template(item[1], item[2]).name
self:say("We need:")
self.room:send("</>" .. tostring(item_name) .. " from")
self.room:send("</>" .. tostring(place) .. ".")
if stage > 6 then
    self.room:send(tostring(self.name) .. " says, 'If you need a new map, say \"<b:green>I lost my map</>\".'")
end$trig$, '2b628c11309195f88dd00eccaa6d19f6'),
  -- data/triggers/163/163_51_moonwell_dryad_map_replacement.lua
  (163, 51, $trig$if not string.find(string.lower(speech), "i lost my map") then
    return true
end

wait(0.2)
local stage = actor:get_quest_stage("moonwell_spell_quest")
if stage <= 6 then
    return true
end

self:command("sigh")
self:say("It will be difficult to complete this ritual without it.")
wait(1)
self:emote("begins to draw a new map.")
wait(2)
self:emote("continues to draw...")
wait(2)
self:emote("continues to draw...")
wait(4)
self:say("There!  All set!")
wait(1)

if stage == 8 then
    self.room:spawn_object(163, 52)
elseif stage == 9 or stage == 10 then
    self.room:spawn_object(163, 53)
elseif stage == 11 then
    self.room:spawn_object(163, 54)
elseif stage == 12 then
    self.room:spawn_object(163, 55)
elseif stage == 7 then
    -- Stage 7: no map yet — dryad's redraw wouldn't have anything to mark.
    self.room:spawn_object(163, 51)
else
    self.room:spawn_object(163, 51)
end
self:command("give map " .. tostring(actor.name))$trig$, '8a99fb8b78c85435dc2d897b2024ebe8'),
  -- data/triggers/163/163_52_moonwell_heartstone_receive.lua
  (163, 52, $trig$if actor:get_quest_stage("moonwell_spell_quest") == 3 then
    wait(0.2)
    actor:advance_quest("moonwell_spell_quest")
    actor:send(tostring(self.name) .. " tells you, 'Very good! This will work perfectly as an anchor stone.'")
    self.room:send(tostring(self.name) .. " places " .. tostring(object.shortdesc) .. " in the center of the well's outline.")
    self:destroy_item("jewel")
    wait(1.5)
    actor:send(tostring(self.name) .. " tells you, 'Back when I was still mortal, I frequently traveled with")
    actor:send("</>Eleweiss, a ranger of great skill and magical acumen.  We once ventured north")
    actor:send("</>into the frozen mountains, and came across a cult that worshipped a")
    actor:send("</>particularly nasty white dragon.  Due to some unfortunate circumstances, we")
    actor:send("</>ended up having to battle the dragon and were forced to retreat.'")
    wait(2)
    actor:send(tostring(self.name) .. " tells you, 'In our retreat, Eleweiss lost a flask which contained")
    actor:send("</>water blessed by the Goddess Herself.  That water would be ideal for our magic")
    actor:send("</>well.'")
    wait(2)
    actor:send(tostring(self.name) .. " tells you, 'I imagine the flask is the kind of thing a dragon would")
    actor:send("</>add to its treasure hoard.  Please take revenge for us and obtain the flask.'")
end$trig$, '0c6533a6b6040f7695c261df9345003c'),
  -- data/triggers/163/163_53_moonwell_flask_receive.lua
  (163, 53, $trig$if actor:get_quest_stage("moonwell_spell_quest") == 4 then
    wait(0.2)
    self:destroy_item("flask")
    actor:send(tostring(self.name) .. " tells you, 'How did you get this?  No no, go get it yourself.'")
elseif actor:get_quest_stage("moonwell_spell_quest") == 5 then
    wait(0.2)
    self:destroy_item("flask")
    actor:advance_quest("moonwell_spell_quest")
    actor:send(tostring(self.name) .. " tells you, 'Thank you, thank you.'")
    wait(1.5)
    self.room:send(tostring(self.name) .. " opens the flask and pours the water into the boundary of the well while reciting a prayer to Mielikki.")
    wait(0.4)
    self.room:send("The boundary of the well becomes translucent and starts to glow!")
    wait(1.5)
    actor:send(tostring(self.name) .. " tells you, 'Okay now we need some items of power to place around the")
    actor:send("</>outside edge of the well.'")
    wait(1.5)
    actor:send(tostring(self.name) .. " tells you, 'Each needs to be either an orb or circle to reflect the")
    actor:send("</>circular boundary of the well itself.'")
    wait(1.5)
    actor:send(tostring(self.name) .. " tells you, 'The first item shall be a ring representing Fire.  Fire")
    actor:send("</>is most closely associated with rubies, so a ruby ring would be good.  One from")
    actor:send("</>a place connected with fire would be ideal!'")
    wait(0.5)
    actor:send(tostring(self.name) .. " tells you, 'Oh, before you leave.  Here takes this.'")
    self.room:spawn_object(163, 51)
    self:command("give map " .. tostring(actor.name))
    actor:send(tostring(self.name) .. " tells you, 'That will help you keep track of everything.'")
    wait(3)
    actor:send(tostring(self.name) .. " tells you, 'Now go!'")
end$trig$, '9fc263d5b0bf9a2407f9a1eb9f0a512d'),
  -- data/triggers/163/163_54_moonwell_ruby_receive.lua
  (163, 54, $trig$if actor:get_quest_stage("moonwell_spell_quest") == 6 then
    wait(0.2)
    actor:set_quest_var("moonwell_spell_quest", "map", 1)
    actor:send(tostring(self.name) .. " tells you, 'Good.  Thank you!'")
    wait(1.5)
    self.room:send(tostring(self.name) .. " places " .. tostring(object.shortdesc) .. " along the circumference of the circle and utters a prayer.")
    wait(1)
    self.room:send(tostring(object.shortdesc) .. " starts flickering with sparking lights!")
    wait(2)
    actor:send(tostring(self.name) .. " tells you, 'Now that we have the first symbol, we can go for the")
    actor:send("</>second.  The second item we need is an orb, representing the element of Air.")
    actor:send("</>This orb is somewhere in a dark fortress to the east.  Please obtain the orb.'")
    wait(1.5)
    actor:send(tostring(self.name) .. " tells you, 'Oh wait, please allow me to update your map.'")
    world.destroy(object)
end$trig$, '1430e836a9941ea0b6fab2d8bb2a2de5'),
  -- data/triggers/163/163_55_moonwell_map_1_receive.lua
  (163, 55, $trig$if actor:get_quest_stage("moonwell_spell_quest") ~= 6 then
