  -- data/triggers/172/172_01_ill-subclass_grand_master_greeting.lua
  (172, 1, $trig$-- The DG switch on the quest stage: case 0 greets a sorcerer and falls through to
-- case 1 (a no-op, then break); stage 1 does nothing; every later stage is the default.
local stage = actor:get_quest_stage("illusionist_subclass")
if stage == 0 then
    if string.find(actor.class, "sorcerer") and actor.level >= 10 and actor.level <= 45 then
        wait(1)
        actor:send(tostring(self.name) .. " says, 'Hello, " .. tostring(actor.name) .. ".'")
        wait(2)
        actor:send(tostring(self.name) .. " says, 'I'm looking for bright young sorcerers like yourself to become illusionists.  But I need evidence of your dedication...  And resourcefulness.'")
        wait(3)
        actor:send(tostring(self.name) .. " says, 'Do you have time to do a small favor for me?'")
    end
end

if stage > 1 and not actor:get_has_completed("illusionist_subclass") then
    wait(1)
    self:command("smile " .. tostring(actor.name))
    wait(1)
    actor:send(tostring(self.name) .. " says, 'Quest going well, I hope?  Say <b:cyan>'help'</> if you're having any trouble.'")
end$trig$, '0ebd8b38cbfd1f1dc841764e01a97019'),
  -- data/triggers/172/172_04_ill-subclass_grand_master_restarts.lua
  (172, 4, $trig$local speech_lower = string.lower(speech)
if not string.find(speech_lower, "restart") then
    return true  -- keyword not heard
end

if string.find(actor.class, "sorcerer")
    and actor.level > 9 and actor.level < 46
    and actor:get_quest_stage("illusionist_subclass") > 0 then
    wait(0.2)
    actor:send(tostring(self.name) .. " says, 'Very well, if you insist.'")
    actor:restart_quest("illusionist_subclass")
    wait(1)
    self:emote("rummages about in his things.")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'Here is another vial.'")
    wait(1)
    self.room:spawn_object(172, 15)
    self:command("give vial " .. tostring(actor.name))
    wait(2)
    actor:send(tostring(self.name) .. " says, 'And don't muck it up this time!'")
end$trig$, 'c3bf8fedd92927d67c588f88fbbc6de0'),
  -- data/triggers/172/172_05_ill-subclass_return_the_choker_to_the_grand_master.lua
  (172, 5, $trig$if actor:get_quest_stage("illusionist_subclass") == 6 then
    wait(0.2)
    self:destroy_item("choker")
    wait(0.2)
    self:command("smile " .. tostring(actor.name))
    wait(1)
    actor:send(tostring(self.name) .. " says, 'Fantastic work!  The smugglers must be in utter disarray!  You've done well.'")
    wait(3)
    actor:send(tostring(self.name) .. " says, 'I can see that your skill in misdirection is extremely extremely promising.  You have my leave to join the illusionists.'")
    wait(4)
    actor:send(tostring(self.name) .. " says, 'Now, type <b:magenta>'subclass'</>.'")
    actor:complete_quest("illusionist_subclass")
    wait(2)
    self:command("wink " .. tostring(actor.name))
    return true
end

wait(0.2)
self:command("frown")
wait(2)
self:emote("peers closely at the choker.")
wait(3)
actor:send(tostring(self.name) .. " says, 'I'm sorry... there must be some mistake.  This isn't the choker I gave Cestia.'")
wait(1)
actor:send(tostring(self.name) .. " says, 'I'm certain of it.'")
wait(2)
self:emote("returns the choker.")
return true$trig$, '6b43ce80e98ff1efdd9da48be07a785b'),
  -- data/triggers/172/172_06_ill-subclass_drop_the_vial.lua
  (172, 6, $trig$wait(0.1)
local room_zone = actor.room.zone_id
local room_id = actor.room.local_id
local in_hideout = room_zone == 363 and room_id >= 15 and room_id <= 39

if not (in_hideout and actor:get_quest_stage("illusionist_subclass") == 1) then
    self.room:send("The vial breaks easily, and a small gray puff of gas quickly disperses.")
    self.room:send("A sense of magic is felt, but it quickly fades.")
    self.room:send("It appears as though something has gone wrong.")
    world.destroy(self)
    return false
end

self.room:send("The vial breaks easily, and the small gray puff of gas quickly disperses.")
self.room:send("As the moments pass, you sense a magical tension building.")
self.room:send("It spreads outward as its strength grows.")
actor:advance_quest("illusionist_subclass")

-- Scan the room for any smuggler who could have noticed.
local smuggler_found = false
local chief_found = false
local leader_found = false
for _, person in ipairs(self.room:get_people()) do
    local incapacitated = person:has_effect(Effect.Blind)
        or string.find(person.stance or "", "mortally")
        or string.find(person.stance or "", "incapacitated")
        or string.find(person.stance or "", "stunned")
        or string.find(person.stance or "", "sleeping")
    if not incapacitated and person.zone_id == 363 then
        if person.local_id == 0 or person.local_id == 3 or person.local_id == 4 then
            smuggler_found = true
        elseif person.local_id == 6 then
            chief_found = true
            smuggler_found = true
        elseif person.local_id == 1 then
            leader_found = true
            smuggler_found = true
        end
    end
end

if leader_found then
    wait(1)
    local gannigan = self.room:find_actor("gannigan")
    if gannigan then
        gannigan:command("gasp")
        gannigan:say("Cestia... what on earth are you doing?")
    end
elseif chief_found then
    wait(1)
    local chief = self.room:find_actor("chief")
    if chief then
        chief:say("Hrnn?  Irksome wench!  Gannigan shall hear of this!")
    end
elseif smuggler_found then
    wait(1)
    local smuggler = self.room:find_actor("smuggler")
    if smuggler then
        smuggler:emote("looks somewhat confused, but also suspicious.")
        smuggler:say("Hey... ummm...  I'd better let the big guy know you're up to something...  No offense ma'am, but that didn't look too innocent.")
    end
end

if smuggler_found then
    actor:advance_quest("illusionist_subclass")
end

world.destroy(self)
return false$trig$, 'b72b219df8e04b67535ff1f0c1345acb'),
  -- data/triggers/172/172_07_ill-subclass_gannigan_greets_the_quester.lua
  (172, 7, $trig$wait(2)
-- switch on actor:get_quest_stage("illusionist_subclass")
do
    local _sw1 = string.lower(tostring(actor:get_quest_stage("illusionist_subclass") or ""))
    if tonumber(_sw1) == 1 or tonumber(_sw1) == 2 then
        self:emote("looks up from his paperwork briefly.")
        wait(1)
        self:emote("gasps in surprise, and rises quickly from his chair!")
        wait(1)
        self:command("hug " .. tostring(actor.name))
        wait(3)
        self:say("Cestia... my beloved.  Where have you been?")
    elseif tonumber(_sw1) == 3 then
        self:emote("looks up from his paperwork.  He seems angry.")
        wait(1)
        self:say("So.  Already up to your old tricks?")
        wait(2)
        self:emote("appears saddened, but angry nonetheless.")
        wait(3)
        self:say("I am aware of the spell you cast, here in my home.  Tell me, what madness awaits us?")
    elseif tonumber(_sw1) == 4 then
        self:say("Please, Cestia!  You must conceal yourself!  The forces of Mielikki will not overlook your crimes again!")
        wait(3)
        actor:send(tostring(self.name) .. " looks upon you with pleading in his eyes.")
        self.room:send_except(actor, tostring(self.name) .. " looks upon " .. tostring(actor.name) .. " with pleading in his eyes.")
        wait(2)
        self:say("You do remember the incantation, don't you?")
    elseif tonumber(_sw1) == 5 then
        self:say("A raid?  How did you get the townsfolk back on your side?  It would be an amazing accomplishment -")
        wait(3)
        self:say("- if not for the vileness that must lie within your heart to turn upon me so!")
    else
        self:emote("looks up from his paperwork briefly.")
        wait(2)
        self:command("snort")
    end
end$trig$, '59ce6daf02d391950687930ab5dda9fe'),
  -- data/triggers/172/172_08_ill-subclass_tell_gannigan_no.lua
  (172, 8, $trig$local speech_lower = string.lower(speech)
