  -- data/triggers/172/172_10_ill-subclass_reveal_the_walkway.lua
  (172, 10, $trig$local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "where")
    and string.find(speech_lower, "dough")
    and string.find(speech_lower, "rises")) then
    return true  -- not the full incantation
end

if actor:get_quest_stage("illusionist_subclass") ~= 4 then
    return true
end

wait(1.5)
self.room:send("The illusion falls like a sheet of water, revealing in a moment a walkway.")
self.room:send("It snakes eastward across the face of the falls, narrow and dangerous.")
get_room(363, 39):exit("east"):set_state({hidden = false, description = "A narrow walkway zigzags through the air."})
wait(8)
self.room:send("The walkway fades, revealing nothing but a misty drop into the waters below.")
get_room(363, 39):exit("east"):set_state({hidden = true, description = "The balcony ends at the waterfall.  Oddly, there is no railing at this end."})$trig$, '3dee9b14f6aadc6106fef0bfb2132ed3'),
  -- data/triggers/172/172_14_ill-subclass_grand_master_answers_help.lua
  (172, 14, $trig$local speech_lower = string.lower(speech)
if not string.find(speech_lower, "help") then
    return true  -- keyword not heard
end
wait(1)
-- switch on actor:get_quest_stage("illusionist_subclass")
do
    local _sw1 = string.lower(tostring(actor:get_quest_stage("illusionist_subclass") or ""))
    if tonumber(_sw1) == 1 then
        actor:send(tostring(self.name) .. " says, 'Ok, ok, here's what you need to do: Go to the smuggler's hideout, <b:cyan>drop the vial</>, and go to see the leader.'")
        wait(4)
        actor:send(tostring(self.name) .. " says, 'Don't let anyone see you drop the vial!'")
        wait(4)
        actor:send(tostring(self.name) .. " says, 'And get that choker!  Now go.'")
    elseif tonumber(_sw1) == 2 or tonumber(_sw1) == 4 then
        actor:send(tostring(self.name) .. " says, 'Hmm.  Did things get confusing?  Say <b:cyan>'restart'</> if you want to try again.'")
    elseif tonumber(_sw1) == 3 or tonumber(_sw1) == 5 then
        actor:send(tostring(self.name) .. " says, 'Someone saw you drop the vial?")
        wait(3)
        self:command("shake")
        wait(3)
        actor:send(tostring(self.name) .. " says, 'You'll never fool them that way!'")
        wait(3)
        actor:send(tostring(self.name) .. " says, 'Give it some time.  Then come back here and say <b:cyan>'restart'</> to try again.'")
    elseif tonumber(_sw1) == 6 then
        actor:send(tostring(self.name) .. " says, 'You got the choker, you say?  Hand it over!'")
    else
        actor:send(tostring(self.name) .. " says, 'Help you?  Something the matter?'")
        wait(3)
        actor:send(tostring(self.name) .. " says, 'Psyche!  You don't work for me, I wasn't really concerned.'")
    end
end$trig$, '42c56cf8dece369914e8126c83f43ace'),
  -- data/triggers/172/172_17_ill-subclass_smugglers_react_to_quester.lua
