  -- data/triggers/237/237_28_serin-receive.lua
  (237, 28, $trig$-- Converted from DG Script #23728: serin-receive
-- Original: MOB trigger, flags: RECEIVE, probability: 100%
-- Responding to trigger 23723 after they actually have the items.
-- Tracks each treasure individually via quest vars; on the third real piece,
-- advances and completes the quest with an XP/badge reward.

-- Helper: identify which elven treasure (zone 520) was offered.
-- Returns one of: "boots", "cloak", "ring", "cursed_boots", "cursed_cloak",
-- "cursed_ring", or nil for anything else.
local function identify_treasure(obj)
    if obj.zone_id ~= 520 then
        return nil
    end
    local id = obj.local_id
    if id == 8 then return "boots"
    elseif id == 24 then return "cursed_boots"
    elseif id == 9 then return "cloak"
    elseif id == 26 then return "cursed_cloak"
    elseif id == 1 then return "ring"
    elseif id == 18 then return "cursed_ring"
    end
    return nil
end

if actor.is_npc then
    return true
end
if actor.level > 99 then
    wait(1)
    self:command("eyebrow")
    return true
end

local boots = actor:get_quest_var("sunfire_rescue:boots") or 0
local cloak = actor:get_quest_var("sunfire_rescue:cloak") or 0
local ring = actor:get_quest_var("sunfire_rescue:ring") or 0

if actor:get_has_completed("sunfire_rescue") then
    self:say("You have already helped me.  I am grateful to you.")
    return true
end

if actor:get_quest_stage("sunfire_rescue") ~= 1 then
    self:say("What are you doing?")
    return true
end

local kind = identify_treasure(object)

-- Reject cursed items outright.
if kind == "cursed_boots" then
    self:emote("looks at the boots carefully.")
    self.room:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
    self.room:send(tostring(self.name) .. " says, 'These are the cursed boots.  If you have the real ones,")
    self.room:send("</>please...  These cannot help me at all.  Do you have the real ones?  I need")
    self.room:send("</>them.'")
    return true
elseif kind == "cursed_cloak" then
    self:emote("runs his hands over the cloak quickly.")
    self:say("This is the cursed cloak!")
    self:emote("looks angry.")
    actor:send("shoves " .. tostring(object.shortdesc) .. " back in your face.")
    self.room:send_except(actor, "shoves " .. tostring(object.shortdesc) .. " back in " .. tostring(actor.name) .. "'s face.")
    wait(1)
    self:say("Well?  Do you have the real cloak to give to me?")
    self:emote("taps his foot impatiently.")
    return true
elseif kind == "cursed_ring" then
    self:command("frown " .. tostring(actor.name))
    self.room:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
    self:say("What kind of cruel trick is this?")
    wait(1)
    self:say("Well, do you have the real one to give to me?")
    return true
end

-- Real treasures: accept each at most once.
if kind == "boots" then
    if boots == 1 then
        self:say("You have already given me these.")
        return true
    end
    actor:set_quest_var("sunfire_rescue", "boots", 1)
    boots = 1
    wait(0.2)
    world.destroy(object)
    self:command("smile " .. tostring(actor.name))
    self:say("Thank you.")
    wait(1)
elseif kind == "cloak" then
    if cloak == 1 then
        self:say("You have already given me the cloak.")
        return true
    end
    actor:set_quest_var("sunfire_rescue", "cloak", 1)
    cloak = 1
    wait(0.2)
    world.destroy(object)
    self:emote("carefully looks at the cloak.")
    self:say("This is it!  Thank you!")
    wait(1)
    self:say("Then I can finally escape....")
elseif kind == "ring" then
    if ring == 1 then
        self:say("You have already given me this ring.")
        return true
    end
    actor:set_quest_var("sunfire_rescue", "ring", 1)
    ring = 1
    wait(0.2)
    self.room:send("Looking at the ring, the prisoner looks overwhelmed with emotion.")
    self:say("Escape is so close I can feel it!")
    world.destroy(object)
else
    self:say("This isnt going to help me!")
    self:command("roll")
    return true
end

-- Has the player now turned in all three treasures?
local total = boots + cloak + ring
if total < 3 then
    wait(1)
    self:say("Do you have the other treasures of my people?")
    return true
end

-- All three -- complete the quest.
wait(2)
self:emote("slips his feet out of the shackles and wears the boots.")
wait(2)
self:emote("unshackles his arms and wears the cloak on his shoulders.")
wait(2)
self.room:send("Looking hesitant, the prisoner slowly slides the ring onto his finger.")
actor:advance_quest("sunfire_rescue")
self.room:spawn_object(237, 16)
self:destroy_item("all.elven")
wait(3)
self:emote("vanishes from sight.")

-- The badge reward is level 50, but the players have to be 70 or so
-- to handle the boots, cloak etc anyway.
local expcap
if actor.level < 85 then
    expcap = actor.level
else
    expcap = 85
end

local expmod
if expcap < 9 then
    expmod = (((expcap * expcap) + expcap) / 2) * 55
elseif expcap < 17 then
    expmod = 440 + ((expcap - 8) * 125)
elseif expcap < 25 then
    expmod = 1440 + ((expcap - 16) * 175)
elseif expcap < 34 then
    expmod = 2840 + ((expcap - 24) * 225)
elseif expcap < 49 then
    expmod = 4640 + ((expcap - 32) * 250)
elseif expcap < 90 then
    expmod = 8640 + ((expcap - 48) * 300)
else
    expmod = 20940 + ((expcap - 89) * 600)
end

-- Adjust exp award by class so all classes receive the same proportionate amount.
if actor.class == "warrior" or actor.class == "berserker" then
    -- 110% of standard
    expmod = expmod + (expmod / 10)
elseif actor.class == "paladin" or actor.class == "anti-paladin" or actor.class == "ranger" then
    -- 115% of standard
    expmod = expmod + ((expmod * 2) / 15)
elseif actor.class == "sorcerer" or actor.class == "pyromancer" or actor.class == "cryomancer" or actor.class == "illusionist" or actor.class == "bard" then
    -- 120% of standard
    expmod = expmod + (expmod / 5)
elseif actor.class == "necromancer" or actor.class == "monk" then
    -- 130% of standard
    expmod = expmod + ((expmod * 2) / 5)
end

actor:send("<b:yellow>You gain experience!</>")
local setexp = expmod * 10
for _ = 1, 10 do
    actor:award_exp(setexp)
end
actor:complete_quest("sunfire_rescue")
wait(2)
actor:send(tostring(self.name) .. " whispers to you, 'Thank you for your help!  Please wear this badge as a token of my respect.'")
self:command("give badge " .. tostring(actor.name))
wait(2)
self.room:send("A voice softly echos, 'Good-bye...'")
world.destroy(self.room:find_actor("serin"))
return true$trig$, 'dbb0732c5767db4173eb0eeeb47a6afb'),
  -- data/triggers/237/237_50_vilekka-greet.lua
  (237, 50, $trig$-- Converted from DG Script #23750: vilekka-greet
-- Original: MOB trigger, flags: GREET, probability: 100%
-- The vilekka_stew quest greet -- evil/neutral entry point for the
-- High Priestess. Good-aligned visitors are sneered at and teleported
-- back to room 237/93. Stage-aware reminders for in-progress players.
if actor.is_npc or actor.level > 99 or actor:get_has_completed("vilekka_stew") then
    return true
end
wait(1)
-- If they are coming back with the items she said to fetch...
-- Starting with the heart of the drow master from Anduin...
if actor:get_quest_stage("vilekka_stew") == 1 then
    self.room:send("The High Priestess says, 'Well? Do you have the heart of that traitor?'")
    self.room:send("She looks greedy.  'Give it to me if you do.  You may ask about your <b:white>[progress]</> if you need.'")
elseif actor:get_quest_stage("vilekka_stew") == 2 then
    self:command("wink " .. tostring(actor.name))
    self:say("Well?  Continue now or stop?")
elseif actor:get_quest_stage("vilekka_stew") == 3 then
    -- Here we have the second stage, the head of the drider king
    self:say("Well?  Have you brought me the head of my enemy?")
    self.room:send("The High Priestess licks her lips.")
    wait(1)
    self.room:send(tostring(self.name) .. " says, 'Give it to me.  You may ask about your <b:white>[progress]</> if you need.'")
elseif actor:get_quest_stage("vilekka_stew") == 4 then
    self:command("grin " .. tostring(actor.name))
    self:say("Well?  Do you wish to continue now?")
elseif actor:get_quest_stage("vilekka_stew") == 5 then
    -- Now here we have the player supposedly returning with spices and herbs.
    self.room:send(tostring(self.name) .. " says, 'At last, I can carry out the Spider Queen's orders!  Give me the spices and herbs!  The finest of the realm!  Ask for a reminder of your <b:white>[progress]</> if you need.'")
else
    -- IE, if they haven't started the quest.
    if actor.alignment < 349 then
        actor:send(tostring(self.name) .. " looks up at you.")
        self.room:send_except(actor, tostring(self.name) .. " looks up at " .. tostring(actor.name) .. ".")
        self.room:send("She says, 'Welcome to my city!  All who are not followers of the path of good are welcome here.'")
        wait(2)
        actor:send("She looks closely at you.")
        self.room:send_except(actor, "She looks closely at " .. tostring(actor.name) .. ".")
        self.room:send(tostring(self.name) .. " says, 'In fact, perhaps you can help me.  Yes, I think you can help me perform a great service to the city.'")
    else
        actor:send(tostring(self.name) .. " sneers at you.")
        self.room:send_except(actor, tostring(self.name) .. " sneers at " .. tostring(actor.name) .. ".")
        self:say("So, you think you can just wander around my city?")
        self.room:send(tostring(self.name) .. " laughs.")
        wait(1)
        self.room:send(tostring(self.name) .. " says, 'Get out of my sight.  I find your presence annoying.'")
        wait(1)
        self.room:send_except(actor, "<magenta>Vilekka gestures at " .. tostring(actor.name) .. ", and " .. tostring(actor.name) .. " disappears.</>")
        actor:teleport(get_room(237, 93))
        wait(0.1)
        get_room(237, 93):at(function()
            actor:send("<magenta>Vilekka gestures at you, and your vision wavers...</>")
        end)
        -- Can't use mat while forcing them to look - they will see the
        -- priestess as she is temporarily in the room due to mat.
        get_room(237, 93):at(function()
            actor:send("You find yourself back in the temple.")
        end)
    end
end$trig$, 'e728ff8363d294f042fb4f0fca38ea53'),
  -- data/triggers/237/237_53_vilekka-eeew.lua
  (237, 53, $trig$-- Converted from DG Script #23753: vilekka-eeew
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: disgusting disgusting?
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "disgusting") then
    return true  -- No matching keywords
end
-- OK, this is in response to 23752, the returning of the Drider King's
-- head. (Why is she questioning? Check 23754 part 2..her goddess
-- is requiring that she eat the head and heart the player returns to her.
wait(0.2)
if (actor.is_player) and (actor:get_quest_stage("vilekka_stew") == 5) then
    self:emote("looks shrewdly around the room.")
    wait(2)
    self:say("It is not that I question the will of my Goddess...")
    wait(2)
    self.room:send(tostring(self.name) .. " says, 'But perhaps it can be made easier.")
    wait(3)
    self.room:send(tostring(self.name) .. " says, 'The Spider Queen requires of me that I eat this head and this heart.'")
    wait(4)
    self:say("But she did not say I should eat them plain.")
    self:emote("gets a wicked expression on her face.")
    wait(4)
    self.room:send(tostring(self.name) .. " says, 'You!  " .. tostring(actor.name) .. "!  Bring me the ten finest herbs and spices from the realm!  I do not care where you get them from, but make sure they are the finest!'")
    wait(5)
    self:say("Return them to me and I will surely reward you.")
    self:command("wink " .. tostring(actor.name))
    wait(3)
    self.room:send(tostring(self.name) .. " says, 'Ask for a reminder of your <b:white>[progress]</> if you need.'")
    self.room:send("<b:white>Quest credit will only be awarded individually</>.")
end$trig$, '7d6bf0a6b5ef6233ebfee697e2172822'),
  -- data/triggers/237/237_54_continue-advancing.lua
  (237, 54, $trig$-- Converted from DG Script #23754: continue-advancing
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: continue
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "continue") then
    return true  -- No matching keywords
end
-- OK, this is in two parts.  It represents the player wishing to
-- continue the quest rather than stopping and accepting
-- a lesser prize.  The first one is after returning the
-- drow master's heart (the dude from Anduin) and the second
-- is after returning the drider king's head (who's in
-- this area).  It follows trigger 23752 parts 1 and 2.
wait(0.2)
if actor.is_player then
    if actor:get_quest_stage("vilekka_stew") == 4 then
        actor:advance_quest("vilekka_stew")
        actor:send("<b:white>You have advanced the quest!</>")
        self:emote("looks pleased.")
        self.room:send("The High Priestess begins chanting to her goddess.")
        wait(2)
        self:emote("continues to chant...")
        wait(4)
        self:emote("looks like she just swallowed something very unpleasant.")
        self:say("Disgusting.")
    elseif actor:get_quest_stage("vilekka_stew") == 2 then
        actor:advance_quest("vilekka_stew")
        actor:send("<b:white>You have advanced the quest!</>")
        self:say("Yes, the driders....")
        self:command("shudder")
        wait(2)
        self.room:send(tostring(self.name) .. " says, 'Driders are ancient enemies of all true drow.  A drider is a half-drow, half-spider abomination.  When a young drow fails the coming of age test that the Spider Queen requires, it is turned into a drider as punishment and exiled from our race.'")
        wait(4)
        self.room:send(tostring(self.name) .. " says, 'I say \"it\", but all drow who have ever failed the test have been male.'")
        wait(3)
        self.room:send(tostring(self.name) .. " says, 'Males are weak and inferior.  So they often become driders.'")
        wait(3)
        self:command("sigh")
        self:say("They have lately been harassing Dheduu.")
        wait(2)
        self.room:send(tostring(self.name) .. " says, 'Bring me the head of their king!  That should discourage them.'")
        self:command("cackle")
        wait(2)
        self.room:send(tostring(self.name) .. " says, 'You may ask about your <b:white>[progress]</> if you need.'")
        wait(2)
        self:emote("waves you away.  'Go on.'")
    end
end$trig$, '42b1b2e96e33006408c6891e1f48bb53'),
  -- data/triggers/237/237_98_sunfire_rescue_status_checker.lua
  (237, 98, $trig$-- Converted from DG Script #23798: sunfire_rescue_status_checker
-- Original: MOB trigger, flags: SPEECH, probability: 100%
-- "progress" report for the sunfire_rescue quest. Lists which of the three
-- elven treasures (boots, cloak, ring) Serin still needs.

-- Speech keywords: progress progress?
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "progress") then
    return true  -- No matching keywords
end
wait(0.2)
local boots = actor:get_quest_var("sunfire_rescue:boots") or 0
local cloak = actor:get_quest_var("sunfire_rescue:cloak") or 0
local ring = actor:get_quest_var("sunfire_rescue:ring") or 0
local total = boots + cloak + ring
if actor:get_quest_stage("sunfire_rescue") == 1 then
    self:say("Please find the treasures of my people!")
    if total > 0 then
        self.room:send("</>You have retrieved the following treasures:")
        if boots == 1 then
            self.room:send(tostring(objects.template(520, 8).name) .. ".")
        end
        if cloak == 1 then
            self.room:send(tostring(objects.template(520, 9).name) .. ".")
        end
        if ring == 1 then
            self.room:send(tostring(objects.template(520, 1).name) .. ".")
        end
    end
    if total < 3 then
        self.room:send("</>You still need to bring me:")
        if boots == 0 then
            self.room:send(tostring(objects.template(520, 8).name) .. ".")
        end
        if cloak == 0 then
            self.room:send(tostring(objects.template(520, 9).name) .. ".")
        end
        if ring == 0 then
            self.room:send(tostring(objects.template(520, 1).name) .. ".")
        end
    end
elseif actor:get_has_completed("sunfire_rescue") then
    self:say("You have already helped me greatly.")
end$trig$, '57e09ebf647b61b3c06c22a6ad62a53c'),
  -- data/triggers/237/237_99_vilekka_stew_status_check.lua
  (237, 99, $trig$-- Converted from DG Script #23799: vilekka_stew_status_check
-- Original: MOB trigger, flags: SPEECH, probability: 100%
-- "progress" report for the vilekka_stew quest. Lists current stage hint
-- and, on stage 5, which of the ten herbs/spices have been delivered.

-- Speech keywords: progress progress?
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "progress") then
    return true  -- No matching keywords
end
wait(0.2)
if actor:get_has_completed("vilekka_stew") then
    self:say("You have already done me a great service.")
    return true
end
local stage = actor:get_quest_stage("vilekka_stew")
do
    local _sw1 = string.lower(tostring(stage or ""))
    if tonumber(_sw1) == 1 then
        self.room:send(tostring(self.name) .. " says, 'Bring me the heart of the drow living in the")
        self.room:send("</>surface city!'")
    elseif tonumber(_sw1) == 2 then
        self:say("Well, do you want to continue or stop?")
    elseif tonumber(_sw1) == 3 then
        self:say("You must bring me the head of the drider king.")
    elseif tonumber(_sw1) == 4 then
        self:say("Well, do you want to continue or stop?")
    elseif tonumber(_sw1) == 5 then
        self.room:send(tostring(self.name) .. " says, 'Bring me some spices so that I can make this head")
        self.room:send("</>and heart palatable.'")
        local num_spices = actor:get_quest_var("vilekka_stew:num_spices") or 0
        -- (key, zone, local_id) for each accepted spice.
        local spices = {
            { "12552", 125, 52 },
            { "49022", 490, 22 },
            { "23750", 237, 50 },
            { "23751", 237, 51 },
            { "23752", 237, 52 },
            { "23753", 237, 53 },
            { "23754", 237, 54 },
            { "23755", 237, 55 },
            { "23756", 237, 56 },
            { "23757", 237, 57 },
            { "23758", 237, 58 },
            { "23759", 237, 59 },
            { "23760", 237, 60 },
        }
        if num_spices > 0 then
            self.room:send("So far you have brought me:")
            for _, s in ipairs(spices) do
                if actor:get_quest_var("vilekka_stew:got_spice:" .. s[1]) == 1 then
                    self.room:send("- " .. tostring(objects.template(s[2], s[3]).name))
            end
        end
        end
        local remaining = 10 - num_spices
        self.room:send("Bring me " .. tostring(remaining) .. " more spices to prepare this stew.")
    else
        self:say("You are not performing a service for me.")
    end
end$trig$, '13b5cad26b00e4b61c1e9e1a54cd9955'),
  -- data/triggers/300/300_00_nasty_sulfur_fumes.lua
  (300, 0, $trig$-- Converted from DG Script #30000: Nasty sulfur fumes
-- Original: WORLD trigger, flags: RANDOM, probability: 40%

-- 40% chance to trigger
if not percent_chance(40) then
    return true
end
if #self.room.actors == 0 then
    return true
end
local victim = self.room.actors[random(1, #self.room.actors)]
if not victim or victim.is_npc then
    return true
end
-- single roll, branched (legacy DG used switch which evaluated once)
local roll = random(1, 10)
if roll == 1 or roll == 2 then
    -- DG case 1 sets damage 1 and has no break: it falls into the case 2 body.
    victim:send("You just inhaled a lungful of sulphurous fumes!  It burns!")
    self.room:send_except(victim, tostring(victim.name) .. " inhales a lungful of fumes and chokes and gags!")
    victim:damage(roll == 1 and 1 or 2)  -- physical
elseif roll == 3 or roll == 4 then
    victim:send("The stinking yellow smoke wafts under your nose, making you sneeze.")
    self.room:send_except(victim, tostring(victim.name) .. " breathes in a bit of yellow smoke, and sneezes.")
elseif roll == 5 or roll == 6 then
    victim:send("Your eyes water from the rotten-smelling smoke.")
    self.room:send_except(victim, tostring(victim.name) .. " blinks as the nasty smoke gets in " .. tostring(victim.possessive) .. " eyes.")
else
    self.room:send("Nasty fumes waft up from the wreckage.  They smell of rotten eggs.")
end
return true$trig$, '78f8c26a896b8a47fa8b14597d66166b'),
  -- data/triggers/300/300_07_receive_enemy_communication.lua
  (300, 7, $trig$-- Converted from DG Script #30007: receive enemy communication
-- Original: MOB trigger, flags: RECEIVE, probability: 100%
-- Branch on the (zone_id, local_id) of the offered item.
-- 302:12 = enemy/orc message scroll (player is acting as a spy for the orcs)
-- 302:8  = paladin message parchment (player is foolishly handing in evidence
--          against themselves; general attacks and kicks them through a door)
if object.zone_id == 302 and object.local_id == 12 then
    wait(0.4)
    self:destroy_item("scroll")
    self:say("Why thank you... good spy.  I'll have my warlocks extract this message,")
    self:say("and find out what those self-righteous paladins are up to.")
    wait(2)
    self:say("Here is something for your trouble.")
    -- Reward: two random gems from the 555:81-555:89 range
    self.room:spawn_object(555, 81 + random(1, 8))
    self.room:spawn_object(555, 81 + random(1, 8))
    self:command("give all.gem " .. tostring(actor.name))
    return false
elseif object.zone_id == 302 and object.local_id == 8 then
    wait(0.3)
    self:destroy_item("parchment")
    self:command("growl")
    wait(2)
    self:say("What are you doing with this!  You spy!  Paladin!  GUARDS!")
    wait(1)
    self:command("open door")
    wait(0.4)
    local damage = actor.level * 2 + 5
    local damage_dealt = actor:damage(damage)  -- crush
    if damage_dealt == 0 then
        self.room:send_except(actor, tostring(self.name) .. " tries to kick " .. tostring(actor.name) .. ", but is having trouble with " .. tostring(self.possessive) .. " foot!")
        actor:send(tostring(self.name) .. " tries to kick you, but is having trouble with " .. tostring(self.possessive) .. " foot!")
    else
        self.room:send_except(actor, tostring(self.name) .. " kicks " .. tostring(actor.name) .. " solidly in the head! (<red>" .. tostring(damage_dealt) .. "</>)")
        actor:send(tostring(self.name) .. " kicks you solidly in the head! (<red>" .. tostring(damage_dealt) .. "</>)")
        self.room:send_except(actor, tostring(actor.name) .. " is sent reeling through the doorway!")
        actor:send("You topple through the door into the next room!")
        wait(0.3)
        actor:teleport(get_room(300, 38))
    end
    return false
else
    self.room:send_except(actor, tostring(actor.name) .. " tries to give " .. tostring(object.shortdesc) .. " to " .. tostring(self.name) .. ".")
    actor:send("You try to give " .. tostring(object.shortdesc) .. " to " .. tostring(self.name) .. ", but " .. tostring(self.name) .. " refuses.")
    wait(1)
    self:say("I don't need your rubbish!  Show some respect, dog!")
    return true
end$trig$, '2ef7b5892f8e2ee9b1a3c4c60986a2a0'),
