  -- data/triggers/302/302_12_banish_murgbol_greet.lua
  (302, 12, $trig$local stage = actor:get_quest_stage("banish")
wait(0.4)
local class_lower = string.lower(actor.class or "")
if string.find(class_lower, "priest") or string.find(class_lower, "diabolist") then
    if (actor:get_quest_var("banish:greet") or 0) ~= 1 then
        if stage == 0 then
            self:say("Wanna learn some spells kid?")
            -- (empty room echo)
            self.room:send(tostring(self.name) .. " says, 'I can teach you to hurl your enemies far into the outer planes")
            self.room:send("</>so they can never bother you again.'")
        else
            if stage == 2 then
                self.room:send(tostring(self.name) .. " says, 'I can already tell you have made progress along your journey.")
                self.room:send("</>Let's keep going!'")
                wait(1)
                self:emote("closes her eyes and prays for further guidance.")
                wait(3)
                self:say("Yes, I see...")
                self:emote("nods.  'Quite challenging...'")
                wait(1)
                self:emote("opens her eyes.")
                wait(2)
                self:say("The gods wish to test your sway over the elemental forces.")
                wait(1)
                self.room:send(tostring(self.name) .. " says, 'Ice elementals wander deep in the frozen tunnels near the nest")
                self.room:send("</>of a mighty dragon.  Destroy the <b:cyan>most powerful of these elementals</> to receive")
                self.room:send("</>your next vision, then return to me.'")
            elseif stage == 3 then
                self.room:send(tostring(self.name) .. " says, 'It seems you've managed to destroy the ice elemental lord.")
                self.room:send("</>Let's press on!'")
                wait(1)
                self:emote("closes her eyes and prays for further guidance.")
                wait(3)
                self:say("Yes, most appropriate.")
                wait(1)
                self:emote("opens her eyes.")
                wait(2)
                self:say("The gods demand a sacrifice of life energy.")
                wait(1)
                self.room:send(tostring(self.name) .. " says, 'A powerful <b:magenta>troll wizard</> warps the tunnels of an ancient mine.")
                self.room:send("</>His blood will most please the gods.  After this is done, return to me.'")
            elseif stage == 4 then
                self.room:send(tostring(self.name) .. " says, 'The gods are greatly pleased with your sacrifice.")
                self.room:send("</>Let's continue!'")
                wait(1)
                self:emote("closes her eyes and prays for further guidance.")
                wait(3)
                self:say("Naturally, such a thing must be done.")
                wait(1)
                self:emote("opens her eyes.")
                wait(2)
                self.room:send(tostring(self.name) .. " says, 'Since you've dispatched something living, it's time to banish")
                self.room:send("</>something lingering after death.'")
                wait(1)
                self.room:send(tostring(self.name) .. " says, 'In a room of art in an ancient burial site waits a <magenta>long-dead</>")
                self.room:send("</><magenta>apparition</>.  Its threads to this world are tenuous at best.  Send it to the")
                self.room:send("</>next world to receive the next part of the prayer.  Afterward, come back and")
                self.room:send("</>we shall continue.'")
            elseif stage == 5 then
                self.room:send(tostring(self.name) .. " says, 'Your awareness continues to grow.")
                self.room:send("</>Let's keep moving!'")
                wait(1)
                self:emote("closes her eyes and prays for further guidance.")
                wait(3)
                self:say("Certainly, as you wish...")
                wait(1)
                self:emote("opens her eyes.")
                wait(2)
                self.room:send(tostring(self.name) .. " says, 'The gods of light will have you undertake the next step and")
                self.room:send("</>prove mastery over demonic energy.'")
                wait(1)
                self.room:send(tostring(self.name) .. " says, 'Far to the north in Frost Valley, there is a &9<blue>demon corrupting</>")
                self.room:send("</>&9<blue>the world around it</> through its very presence.  Exorcise it from Ethilien and")
                self.room:send("</>receive the reward of the gods, then return here.'")
            elseif stage == 6 then
                self.room:send(tostring(self.name) .. " says, 'The gods of light are satisfied.")
                self.room:send("Let's see the final test!'")
                wait(1)
                self:emote("closes her eyes and prays for further guidance.")
                wait(3)
                self:command("grin")
                self:say("Delightful choice.")
                wait(1)
                self:emote("opens her eyes.")
                wait(2)
                self.room:send(tostring(self.name) .. " says, 'Destroying celestial energy for the dark gods shall be your")
                self.room:send("</>final task.'")
                wait(1)
                self.room:send(tostring(self.name) .. " says, 'Many celestial beings have made their home in a floating")
                self.room:send("</>crystal fortress on South Caelia.  One in particular, a <b:white>six-winged seraph</>,")
                self.room:send("</>stands sentinel over the uppermost floors.  Banish it from Ethilien and the")
                self.room:send("</>gods will reward you with the final part of the prayer.  Return to me after,")
                self.room:send("</>and I shall help you perform it.")
            elseif stage == 7 then
                self:say("I see you have been successful!")
                wait(1)
                self:say("Now, speak aloud the mystic word your visions revealed!")
            end
            actor:set_quest_var("banish", "greet", 1)
        end
    end
end$trig$, 'f88bcf8e3ed00681b1d78c148e800ad4'),
  -- data/triggers/302/302_13_banish_murgbol_speech1.lua
  (302, 13, $trig$-- Converted from DG Script #30213: banish_murgbol_speech1
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: yes sure yep okay yeah cool good
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "yes") or string.find(speech_lower, "sure")
        or string.find(speech_lower, "yep") or string.find(speech_lower, "okay")
        or string.find(speech_lower, "yeah") or string.find(speech_lower, "cool")
        or string.find(speech_lower, "good")) then
    return true  -- No matching keywords
end
wait(0.2)
local stage = actor:get_quest_stage("banish")
local class_lower = string.lower(actor.class or "")
if string.find(class_lower, "priest") or string.find(class_lower, "diabolist") then
    if stage == 0 then
        if actor.level > 64 then
            self:say("Good, good...")
            actor:start_quest("banish")
            wait(1)
            self:say("I shall see how the gods best wish me to teach you.")
            self.room:send("She closes her eyes and prays to the gods above and below.")
            wait(7)
            self:say("The gods have decreed you must go on a vision quest.")
            wait(2)
            self.room:send(tostring(self.name) .. " says, 'They demand you demonstrate power over the six animating forces.")
            self.room:send("</>After each demonstration, they'll provide you with a different part of the")
            self.room:send("</>spell to banish your foes.  <b:cyan>Record those visions</> - they're critical to")
            self.room:send("</>unlocking the spell.'")
            wait(7)
            self.room:send(tostring(self.name) .. " says, 'Your first vision will be granted when you prove mastery over")
            self.room:send("</>magical life.  Find the <blue>mighty witch of the sea</> in her lair beneath the waves")
            self.room:send("</>and defeat her.  The gods will give you part of the prayer.'")
            wait(6)
            self:say("Return to me after and I will guide you to your next act.")
            wait(2)
            self.room:send(tostring(self.name) .. " says, 'And if you need a reminder, check in with me on your <b:white>[progress]</>")
            self.room:send("</>any time you feel like it.'")
            wait(2)
            self:say("Now go!")
            actor:set_quest_var("banish", "greet", 1)
        else
            self:say("Give it time kid.  You aren't ready to wield such power.")
        end
    end
end$trig$, '93416815467a202ad9b87bcb160697c4'),
  -- data/triggers/302/302_18_banish_murgbol_speech2.lua
  (302, 18, $trig$-- Speech keyword: vibugp
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "vibugp") then
    return true  -- No matching keywords
end
wait(0.2)
if actor:get_quest_stage("banish") == 7 then
    actor:send(tostring(self.name) .. " chants along with you.")
    self.room:send_except(actor, tostring(self.name) .. " chants along with " .. tostring(actor.name) .. ".")
    self.room:send(tostring(self.name) .. " starts casting, <b:yellow>'Vibugp'</>...")
    wait(2)
    actor:send("There is a bright flash as you feel the power of the spell well up in the words, <b:red>'I banish thee!'</>")
    skills.set_level(actor, "banish", 1000)
    wait(1)
    actor:send("<b:red>You have mastered the prayer for Banish!</>")
    actor:complete_quest("banish")
    if not actor:get_quest_var("hell_trident:helltask5") and actor:get_quest_stage("hell_trident") == 1 then
        actor:set_quest_var("hell_trident", "helltask5", 1)
    end
    self.room:send_except(actor, "There is a bright flash as the spell goes off!")
    self.room:send_except(actor, tostring(actor.name) .. " seems to be more connected to the universe!")
end$trig$, '5768f38c6e0858b52def9c7703c153a5'),
  -- data/triggers/302/302_19_banish_murgbol_status_checker.lua
  (302, 19, $trig$-- Speech keywords: status, progress
-- TODO: Confirm the (zone, local_id) decomposition for each stage's target mob.
-- Original DG Script used legacy global vnums (e.g. 41119 -> zone 411, id 19).
-- These mappings assume zone 0 -> zone 1000 was *not* used by these mobs.
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "status") or string.find(speech_lower, "progress")) then
    return true  -- No matching keywords
end
wait(0.2)
local stage = actor:get_quest_stage("banish")
if actor:get_has_completed("banish") then
    self:say("I have taught you all I can.")
    return true
end
if stage == 0 or stage == nil then
    self:say("I'm not teaching you right now...")
    return true
end
local mob_zone, mob_id, place, known
    do
        local _sw1 = string.lower(tostring(stage or ""))
        if tonumber(_sw1) == 1 then
        mob_zone, mob_id = 411, 19
            place = "her chamber under the ocean waves"
            known = "Nothing."
        elseif tonumber(_sw1) == 2 then
        mob_zone, mob_id = 533, 13
            place = "the frozen tunnels of the north"
            known = "v"
        elseif tonumber(_sw1) == 3 then
        mob_zone, mob_id = 370, 0
            place = "a deep and ancient mine"
            known = "vi"
        elseif tonumber(_sw1) == 4 then
        mob_zone, mob_id = 480, 5
            place = "a room filled with art in an ancient barrow"
            known = "vib"
        elseif tonumber(_sw1) == 5 then
        mob_zone, mob_id = 534, 17
            place = "the cold valley of the far north"
            known = "vibu"
        elseif tonumber(_sw1) == 6 then
        mob_zone, mob_id = 238, 11
            place = "a nearby fortress of clouds and crystals"
            known = "vibug"
        elseif tonumber(_sw1) == 7 then
            self.room:send(tostring(self.name) .. " says, 'Come, speak the prayer aloud: <b:magenta>vibugp</>!'")
        return true
        else
        return true
        end
    end
local mob_name = mobiles.template(mob_zone, mob_id).name
    self.room:send(tostring(self.name) .. " says, 'To learn Banish you must next:'")
self.room:send("- kill " .. tostring(mob_name) .. " in " .. tostring(place) .. ".")
    self.room:send("</>Your knowledge of the prayer so far: \"<b:cyan>" .. tostring(known) .. "</>\"")
return true$trig$, 'ed6bbf0a8eb907c485a63f68712c02e9'),
