  -- data/triggers/364/364_13_berserker_hjordis_command_howl.lua
  (364, 13, $trig$if cmd ~= "howl" then
    return true
end
if actor:get_quest_stage("berserker_subclass") ~= 3 then
    return true
end

actor:advance_quest("berserker_subclass")
actor:send("You raise your voice in a mighty howl to the Spirits!")
self.room:send_except(actor, tostring(actor.name) .. " raises " .. tostring(hisher) .. " voice in a mighty howl to the Spirits!")
wait(0.2)

-- TODO(parity): targets are stored as legacy 5-digit ids (zone*100 + local).
-- This matches the comparisons in 364_14/15/20 which do `self.id`. When the
-- runtime exposes `self.legacy_id` consistently this can stay; otherwise it
-- needs to switch to (zone, local) tuples.
local QUARRIES = {
    { id = 16105, place = "a desert cave"           },
    { id = 16310, place = "some forested highlands" },
    { id = 20311, place = "a vast plain"            },
    { id = 55220, place = "the frozen tundra"       },
}
local pick = QUARRIES[random(1, #QUARRIES)]
local target = pick.id
local place = pick.place

actor:send(tostring(self.name) .. " throws her head back and howls along with you!")
self.room:send_except(actor, tostring(self.name) .. " throws her head back and howls along with " .. tostring(actor.name) .. "!")
wait(2)
actor:set_quest_var("berserker_subclass", "target", target)
local quarry_zone = math.floor(target / 100)
local quarry_local = target % 100
local quarry_name = mobiles.template(quarry_zone, quarry_local).name
actor:send("The Spirits reveal to you a vision of <b:yellow>" .. tostring(quarry_name) .. "</>!")
actor:send("You see it is in <b:yellow>" .. tostring(place) .. "</>!")
wait(6)
actor:send(tostring(self.name) .. " says, 'The Spirits have spoken!'")
wait(2)
actor:send(tostring(self.name) .. " says, 'Find the beast of your Wild Hunt and join our ranks.  Remember, this quest must be undertaken <b:red>ALONE</>.  If you are grouped when you fight your prey, there will be consequences!'")
return true$trig$, '8e5f10880fa88322c0f267f750869c7d'),
  -- data/triggers/364/364_14_berserker_target_fight.lua
  (364, 14, $trig$-- Per-quarry banishment flavor + destination zone. Keys are the quarry's
-- own zone (self.zone_id). `dest_zone` is the wilderness zone the player is
-- exiled into; `room_max` is the highest valid local id in that zone.
local BANISH = {
    [161] = { -- desert cave
        msg_self  = " whips you with her tail and sends you flying into a sandstorm!",
        msg_other = " whips %s with her tail and sends %s flying into a sandstorm!",
        dest_zone = 161, room_max = 85,
    },
    [163] = { -- forested highlands
        msg_self  = " howls and sends you fleeing in terror!",
        msg_other = " howls and sends %s fleeing in terror!",
        dest_zone = 163, room_max = 80,
    },
    [203] = { -- vast plain
        msg_self  = " roars and hurdles you into the blinding heat!",
        msg_other = " roars and hurdles %s into the blinding heat!",
        dest_zone = 203, room_max = 78,
    },
    [552] = { -- frozen tundra
        msg_self  = " roars and hurdles you into the blinding snow!",
        msg_other = " roars and hurdles %s into the blinding snow!",
        dest_zone = 555, room_max = 99,
    },
}

local entry = BANISH[self.zone_id]
if not entry then
    return true
end

-- TODO(parity): the legacy script iterated `room.people` linked-list. The
-- new runtime exposes `room.actors` as an indexable list. If the API uses a
-- different name, this loop needs adjusting.
local actors = self.room.actors or self.room.people or {}
for _, person in ipairs(actors) do
    if person.is_player
        and person:get_quest_stage("berserker_subclass") == 4
        and person.group_size and person.group_size ~= 0
        and person:get_quest_var("berserker_subclass:target") == self.id
    then
        wait(0.2)
        person:send("<b:red>You must hunt this creature alone!  No groups allowed!</>")
        person:send(tostring(self.name) .. entry.msg_self)
        local their_pronoun = person.himher or person.name
        self.room:send_except(person, tostring(self.name) .. string.format(entry.msg_other, person.name, their_pronoun))
        self.room:send_except(person, tostring(person.name) .. " is gone!")
        local roll = random(1, entry.room_max)
        person:teleport(get_room(entry.dest_zone, roll))
    end
end$trig$, '66197087409c210f0de395626bb199b8'),
  -- data/triggers/364/364_19_illusory_wall_new_lenses_replacement.lua
  (364, 19, $trig$-- Speech keyword phrase: must contain "new glasses" to avoid false positives.
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "new glasses") then
    return true
end
if actor:get_quest_stage("illusory_wall") <= 1 then
    return true
end

wait(0.2)
self:say("That's unfortunate!  You'll have to make new ones.")
wait(2)
self:say("Bring me:")
self.room:send("- <b:yellow>A pair of glasses</> or <b:white>small spectacles</> to look through")
self.room:send("- <b:yellow>A prismatic leg spur</> to refract light properly")
self.room:send("- <b:yellow>A small piece of petrified magic</> to enhance the magical sight of the lenses")
wait(4)
self:say("Once you do, you can resume your studies.")
actor:restart_quest("illusory_wall")
actor:set_quest_var("illusory_wall", "103_7",  0)
actor:set_quest_var("illusory_wall", "185_11", 0)
actor:set_quest_var("illusory_wall", "410_5",  0)
actor:set_quest_var("illusory_wall", "510_17", 0)$trig$, '6c4f5000809757b5b04bedc9e93c2c13'),
  -- data/triggers/364/364_20_berserker_subclass_progress_checker.lua
  (364, 20, $trig$-- Speech keywords: subclass, progress
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "subclass") or string.find(speech_lower, "progress")) then
    return true
end

wait(0.2)
local stage = actor:get_quest_stage("berserker_subclass")

if stage == 1 then
    actor:send(tostring(self.name) .. " says, 'There are a few shared rites that bind us together.  None is more revered than the <b:cyan>Wild Hunt</>.'")
    return true
end

if stage == 2 then
    actor:send(tostring(self.name) .. " says, 'Let us challenge the Spirits for the right to prove ourselves!  If they deem you worthy, the Spirits send you a vision of a mighty <b:cyan>beast</>.'")
    return true
end

if stage == 3 then
    actor:send(tostring(self.name) .. " says, '<b:red>Howl</> to the spirits and make your song known!'")
    return true
end

if stage == 4 then
    -- Re-reveal the assigned quarry. Lookup mirrors 364_13's QUARRIES table.
    local QUARRIES = {
        [16105] = "a desert cave",
        [16310] = "some forested highlands",
        [20311] = "a vast plain",
        [55220] = "the frozen tundra",
    }
    local target = actor:get_quest_var("berserker_subclass:target")
    local place = QUARRIES[target]
    if target and place then
        local quarry_name = mobiles.template(math.floor(target / 100), target % 100).name
        actor:send("The Spirits reveal to you a vision of " .. tostring(quarry_name) .. "!")
        actor:send("You see it is in " .. tostring(place) .. "!")
    end
    -- TODO(parity): legacy script also fell through to a race-restriction
    -- "you won't be able to become a berserker" branch with placeholder
    -- "ADD RESTRICTED RACES HERE". Restricted-race list still TBD.
    if not string.find(actor.class, "warrior") then
        actor:send(tostring(self.name) .. " says, 'You won't be able to become a berserker, I'm afraid.'")
    end
    return true
end

-- stage 0 (or unset): not started yet.
if string.find(actor.class, "warrior") then
    if actor.level >= 10 and actor.level <= 25 then
        actor:send(tostring(self.name) .. " says, 'You aren't trying to join us yet!'")
    elseif actor.level < 10 then
        actor:send(tostring(self.name) .. " says, 'You aren't ready to join us yet!'")
    else
        actor:send(tostring(self.name) .. " says, 'You won't be able to become a berserker, I'm afraid.'")
    end
else
    actor:send(tostring(self.name) .. " says, 'You won't be able to become a berserker, I'm afraid.'")
end
return true$trig$, '702260e3b453d1789ac0c7564ccdda36'),
  -- data/triggers/370/370_09_messenger_test_chatter.lua
  (370, 9, $trig$-- Converted from DG Script #37009: Messenger_test_chatter
-- Original: MOB trigger, flags: GREET_ALL, probability: 100%
-- This was probably to be intended as a serial
-- monologue that the messenger spoke at a timed
-- interval.  Maybe this could be a random type
-- of trig that said each of these lines or pieces
-- of related topic at random times.
