                wait(1)
            end
        end
    end
    actor:send("With those words, the Oracle bows his head and refuses to utter another word.")
elseif actor:get_quest_stage("doom_entrance") == 6 then
    local person = actor
    local i = person.group_size
    local a
    if i then
