end$trig$, 'e7a463f8794271134aef9803ace9f969'),
  -- data/triggers/484/484_02_justice-oracle-greet.lua
  (484, 2, $trig$-- Converted from DG Script #48402: justice-oracle-greet
-- Original: MOB trigger, flags: GREET_ALL, probability: 100%
wait(0.2)
