  -- data/triggers/488/488_07_cloud_dragon_fight.lua
  (488, 7, $trig$-- Converted from DG Script #48807: cloud dragon fight
-- Original: MOB trigger, flags: FIGHT, probability: 100%
local mode = random(1, 10)
if mode <= 3 then
    wait(2)
    self:breath_attack("frost", nil)
elseif mode <= 6 then
    wait(2)
    self:command("sweep")
elseif mode <= 8 then
    wait(2)
    self:command("roar")
elseif actor and (actor.room == self.room) and (actor.is_player) then
    wait(1)
    self.room:send(tostring(self.name) .. " suddenly breaks apart into <cyan>millions of droplets of moisture</>!")
    wait(1)
    if actor and (actor.room == self.room) then
        local damage = 350 + random(1, 50)
        if actor:has_effect(Effect.Sanctuary) then
            damage = damage / 2
        end
        local damage_dealt = actor:damage(damage)  -- type: cold
        if damage_dealt == 0 then
            actor:send("<cyan>The cloud of droplets envelopes you, cooling you.</>")
            self.room:send_except(actor, "<cyan>" .. tostring(actor.name) .. " enjoys a nice misting from the cloud.</>")
        else
            actor:send("<cyan>The cloud of droplets envelopes you, draining your energy!</> (<b:red>" .. tostring(damage_dealt) .. "</>)")
            self.room:send_except(actor, "<cyan>" .. tostring(actor.name) .. " gasps for breath as the cloud of droplets envelopes " .. tostring(actor.object) .. "!</> (<blue>" .. tostring(damage_dealt) .. "</>)")
        end
        wait(0.1)
    end
    self.room:send("<cyan>The cloud of droplets coalesces back into the form of " .. tostring(self.name) .. ".</>")
end$trig$, '431de7e3417fc0172e9c86dba2761b0b'),
  -- data/triggers/489/489_15_maid_death_heal_lokari.lua
  (489, 15, $trig$-- Converted from DG Script #48915: maid death heal lokari
-- Original: WORLD trigger, flags: GLOBAL, probability: 100%
--
-- Fired by trigger 14 (any maid's death). Lokari absorbs the dying maid's
-- spirit for 2000 HP. If the cleric maid was the one that died, set the
-- stop-casting flag so trigger 12's in-flight cast aborts.

-- TODO(parity): the original DG checked `random(<#people>)` to pick an actor;
-- the converter approximated that with room.actors but the value isn't really
-- used beyond a non-nil guard. Drop the indirection if the runtime guarantees
-- a triggering context.
if world.count_mobiles(489, 1) > 0 then
    self.room:send("Lokari absorbs the maid's spirit as it leaves her body.")
    get_room(489, 15):at(function()
        self.room:find_actor("lokari"):heal(2000)
    end)
end
wait(0.1)
if world.count_mobiles(489, 23) == 0 then
    globals.stop_casting = 1
end$trig$, '20197967ff70905d077914a9d3345eea'),
