  -- data/triggers/510/510_06_non_clerics_out.lua
  (510, 6, $trig$-- `self` is the room's actor handle; occupants live on its LuaRoom.
local room = self.room
if not room or room.actor_count == 0 then
    return true
end

local rnd = room.actors[random(1, room.actor_count)]
if not rnd or not rnd.is_player or rnd.level >= 100 then
    return true
end

if string.find(rnd.class, "cleric") or string.find(rnd.class, "priest") then
    return true
end

rnd:send("You feel a force pushing you out of the room - you are powerless to resist!")
room:send_except(rnd, tostring(rnd.name) .. " suddenly starts moving out of the room.")
rnd:teleport(get_room(510, 50))
rnd:send("You seem to hear a voice whisper, 'This room is not for you.'")
wait(0.8)
rnd:command("look")$trig$, '3ae08e6e8fc7bacce730ac0f06ed30bc'),
  -- data/triggers/510/510_08_complete_the_book.lua
  (510, 8, $trig$-- Must be wearing the damaged spellbook (510, 22) for the merge.
if not actor:has_equipped(510, 22) then
    actor:send("You can't seem to get a proper grip on it, it almost squirms.")
    return true
end

actor:send("You feel a strong attraction between the book and the magic - you can't hold them apart!")
self.room:send_except(actor, tostring(actor.name) .. " appears to be struggling to keep the book and the magic apart, but vainly.")
wait(1)
self.room:send("The magic melts into the book, and makes it whole!")
wait(0.6)
self.room:send("The book glows more and more brightly!")
actor:send("Ack - the book is heating up too! You don't think you can hold it much longer...")
actor:command("remove book-of-healing")
local damaged = self.room:find_object("book-of-healing")
if damaged then
    world.destroy(damaged)
end
actor:send("You drop the book hurriedly to avoid burning yourself!")
self.room:send_except(actor, tostring(actor.name) .. " drops a large book.")
self.room:spawn_object(510, 23)
world.destroy(self)
return true$trig$, 'b7c54610a4a83f7fd7607d59cdd3f52f'),
  -- data/triggers/510/510_11_give_to_luchiaans.lua
  (510, 11, $trig$local clericquest = clericquest or 0
local magequest = magequest or 0
local zone = object.zone_id
local id = object.id

if zone == 510 and id == 22 then
    -- Damaged book - more work to do.
    wait(0.5)
    self:say("Hmm...a damaged spellbook.")
    wait(2)
    self:say("Look, " .. tostring(actor.name) .. ", why don't you fix this then maybe we can talk.")
    globals.clericquest = 2
    return true
elseif zone == 510 and id == 23 then
    -- Completed spellbook - reward depends on whether they did it solo.
    wait(0.5)
    self:command("grin")
    self:say(tostring(actor.name) .. ", you've done me proud.")
    self:say("Although I guess you haven't really done any favours for the rest of the world!")
    self:command("cackle")
    local book = self.room:find_object("book-of-healing")
    if book then
        world.destroy(book)
    end
    if clericquest == 1 then
        self:say("And you did it all on your own initiative!  Well, here's a gift you can use.")
        self.room:spawn_object(510, 24)
        self:command("give wand " .. tostring(actor.name))
    elseif clericquest == 2 then
        self:say("Even though I had to help you, you did succeed, so here is a small reward.")
        self.room:spawn_object(510, 25)
        self:command("give wand " .. tostring(actor.name))
    else
        self:say("Best of all, I didn't even ask you to do this, so I don't owe you anything.")
        self:command("cackle")
    end
    globals.clericquest = 3
    return true
elseif zone == 510 and id == 28 then
    -- Phoenix heart.
    wait(0.5)
    self:say("Thanks, " .. tostring(actor.name) .. ".")
    self:say("Now I can generate an army of undead, unkillable zombies to help in my plans.")
    self:command("cackle")
    local heart = self.room:find_object("phoenix-heart")
    if heart then
        world.destroy(heart)
    end
    if magequest == 1 then
        self:say("Oh... about that partner thing.  You know I was joking right?")
        self:emote("looks a bit sheepish.")
        self:say("Well... here's a token of my thanks, but that's all you're getting.")
        self.room:spawn_object(510, 29)
        self:command("give green " .. tostring(actor.name))
        globals.magequest = 2
    else
        self:say("It was very generous of you to give this when I didn't ask for it!")
        self:command("grin")
    end
    return true
elseif zone == 85 and id == 50 then
    -- Generic gate item - silently accept and stop.
    return true
else
    -- Unrecognized gift - return it.
    self.room:send_except(actor, tostring(actor.name) .. " gives " .. tostring(object.shortdesc) .. " to " .. tostring(self.name) .. ".")
    actor:send("You give " .. tostring(object.shortdesc) .. " to " .. tostring(self.name) .. ".")
    wait(0.8)
    self:say("What am I supposed to do with this?")
    actor:send(tostring(self.name) .. " returns " .. tostring(object.shortdesc) .. " to you.")
    self.room:send_except(actor, tostring(self.name) .. " returns " .. tostring(object.shortdesc) .. " to " .. tostring(actor.name) .. ".")
    return false
end$trig$, '51600aedcc25c395f86132964f21011e'),
