                actor:send(tostring(self.name) .. " tells you, 'Try typing <b:green>tell instructor hello teacher</>.'")
            elseif tonumber(_sw1) == 3 then
                actor:send(tostring(self.name) .. " tells you, 'Mass communication channels include:")
                -- (empty send to actor)
