            actor:send("Would you like to review?")
            actor:send("You can <b:green>say yes</> or <b:green>say no</>.'")
        end
    end
end
_return_value = true
return _return_value$trig$, '93ae61e1da10b218e686ebf8f95fd6dd'),
  -- data/triggers/520/520_02_break_burning_branch.lua
  (520, 2, $trig$-- Converted from DG Script #52002: break_burning_branch
