  -- data/triggers/533/533_09_ice_wall_sculptor_speech.lua
  (533, 9, $trig$-- Speech keywords: yes, okay, wall, how, ice, supplies
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "yes") or string.find(speech_lower, "okay") or string.find(speech_lower, "wall") or string.find(speech_lower, "how") or string.find(speech_lower, "ice") or string.find(speech_lower, "supplies")) then
    return true  -- No matching keywords
end
wait(0.2)
if actor:get_quest_stage("wall_ice") == 0 then
    if actor.class and string.find(actor.class, "cryomancer") and actor.level > 56 then
        actor:start_quest("wall_ice")
        if actor.gender == "female" then
            self:say("Thank you so much ma'am!")
        elseif actor.gender == "male" then
            self:say("Thank you so much sir!")
        else
            self:say("Thank you so much!")
        end
        wait(1)
        self:say("What I need are blocks of living ice.  Using Wall of Ice I can fuse them together so they make a permanent barrier.  I chewed through my stock pile of living ice faster than I anticipated, so I need more.")
        wait(2)
        self:emote("writes some notes down on a piece of paper.")
        self.room:spawn_object(533, 26)
        self:command("give notes " .. tostring(actor.name))
        wait(2)
        self.room:send(tostring(self.name) .. " says, 'This spell has a chance to capture animated energies of ice creatures in their remains.  Have the spell on you and say <b:cyan>'crystalize'</> in the presence of an ice creature before you defeat it.'")
        wait(4)
        self:say("The more powerful the creature, the more likely this spell will create a block of living ice from it.  But be careful, it only works on creatures actually made of ice!!")
        wait(4)
        self:say("Though there are a number of ice creatures in Frost Valley, any ice creature is fine.  I need 20 more blocks to finish this wall.")
        wait(3)
        self.room:send(tostring(self.name) .. " says, 'You can check your <b:white>[spell progress]</> at any time.'")
    elseif actor:get_quest_stage("wall_ice") == 1 then
        self:say("Hand 'em on over then!")
    end
end$trig$, 'c3b0c7a384637ce85d6772c05bdab1dd'),
  -- data/triggers/533/533_12_wall_ice_sculptor_receive.lua
  (533, 12, $trig$if actor:get_quest_stage("wall_ice") == 1 then
    wait(0.2)
    local blocks = (tonumber(actor:get_quest_var("wall_ice:blocks")) or 0) + 1
    actor:set_quest_var("wall_ice", "blocks", blocks)
    self:say("Great, this is exactly what I need!")
    self.room:send(tostring(self.name) .. " adds " .. tostring(object.shortdesc) .. " to the wall blocking the tunnel.")
    self:destroy_item("all.block-living-ice")
    if blocks == 20 then
        wait(1)
        actor:advance_quest("wall_ice")
        self.room:send(tostring(self.name) .. " says, 'Excellent, this looks like enough ice!  Now all we have to do is cast the spell.  If you'd like to do the honors, just command the ice to <b:cyan>crystalize</>.'")
    else
        wait(0.2)
        self:say("Got any more?")
    end
else
    wait(0.2)
    self:destroy_item("all.block-living-ice")
    self:say("Hey thanks!  I could always use more of those.")
end$trig$, '0d832eedae08040bcf042ce3d7a92cb0'),
  -- data/triggers/533/533_13_spell_progress.lua
  (533, 13, $trig$-- Speech keywords: status, progress
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "status") or string.find(speech_lower, "progress")) then
    return true  -- No matching keywords
end

local stage = actor:get_quest_stage("wall_ice")
if stage == 1 then
    local have = tonumber(actor:get_quest_var("wall_ice:blocks")) or 0
    local need = 20 - have
    wait(0.2)
    self:say("Let me see...")
    self.room:send(tostring(self.name) .. " counts the number of blocks.")
    wait(2)
    self:say("You have brought me <b:cyan>" .. tostring(have) .. " blocks of living ice.</>")
    self:say("I still need <b:cyan>" .. tostring(need) .. "</> more.")
    self.room:send(tostring(self.name) .. " says, 'If you need a new copy of the spell of living ice, say \"<b:cyan>please replace the spell</>\".'")
elseif actor:get_has_completed("wall_ice") then
    self:say("We've already completed the repairs here.  Good work!")
else
    self:say("Did you want to help me work?")
end$trig$, '60c9c6666f146b3e44325f78fd772b23'),
  -- data/triggers/533/533_14_sculptor_refuse.lua
  (533, 14, $trig$-- TODO: Replace with real wand-quest item ID checks once ids are known.
local is_wand_quest_item = false

if is_wand_quest_item then
    return true  -- pass through to other triggers
end

local response
if actor:get_quest_stage("wall_ice") > 0 and actor:get_quest_stage("type_wand") == "wandstep" then
    response = "This won't help us build this wall and I can't craft with it."
elseif actor:get_quest_stage("type_wand") == "wandstep" then
    response = "I can't craft with this."
elseif actor:get_quest_stage("wall_ice") > 0 then
    response = "This won't help us build this wall."
else
    response = "What is this for?"
end

self.room:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
wait(0.2)
self:say(response)
return false  -- block the receive$trig$, '635d58a60928150c5ef7ebd7f164bf98'),
  -- data/triggers/533/533_15_wall_of_ice_spell_replacement.lua
