  -- data/triggers/534/534_50_major_globe_greet.lua
  (534, 50, $trig$-- Converted from DG Script #53450: major_globe_greet
-- Original: MOB trigger, flags: GREET, probability: 100%
if (actor.class == "sorcerer" or actor.class == "cryomancer" or actor.class == "pyromancer") and (actor.level >= 57) then
    if actor:get_has_completed("major_globe_spell") then
        return true
    end
    wait(1)
    -- switch on actor:get_quest_stage("major_globe_spell")
    do
        local _sw1 = string.lower(tostring(actor:get_quest_stage("major_globe_spell") or ""))
        if tonumber(_sw1) == 1 or tonumber(_sw1) == 2 or tonumber(_sw1) == 3 or tonumber(_sw1) == 4 or tonumber(_sw1) == 5 then
            self:emote("coughs fitfully.")
            wait(1)
            actor:send(tostring(self.name) .. " says, 'Have you brought me the salve from Earle?'")
            actor:send(tostring(self.name) .. " looks at you pleadingly.")
            self.room:send_except(actor, tostring(self.name) .. " looks at " .. tostring(actor.name) .. " pleadingly.")
        elseif tonumber(_sw1) == 6 or tonumber(_sw1) == 7 then
            actor:send(tostring(self.name) .. " turns to look at you.")
            self.room:send_except(actor, tostring(self.name) .. " turns to look at " .. tostring(actor.name) .. ".")
            wait(1)
            actor:send(tostring(self.name) .. " says, 'Welcome back, were you able to find the spellbook?'")
        elseif tonumber(_sw1) == 8 then
            actor:send(tostring(self.name) .. " hops up from his chair as you enter.")
            self.room:send_except(actor, tostring(self.name) .. " hops up from his chair as " .. tostring(actor.name) .. " enters.")
            wait(1)
            actor:send(tostring(self.name) .. " comes limping over to you.")
            self.room:send_except(actor, tostring(self.name) .. " limps over to " .. tostring(actor.name) .. ".")
            local wards_left = 5 - actor:get_quest_var("major_globe_spell:ward_count")
            if wards_left > 1 then
                actor:send(tostring(self.name) .. " says, 'The wards!  The wards!  Do you have them?  We still need " .. tostring(wards_left) .. " of them!")
            else
                actor:send(tostring(self.name) .. " says, 'Just one ward left!  Do you have it?'")
            end
        elseif tonumber(_sw1) == 9 or tonumber(_sw1) == 10 then
            actor:send(tostring(self.name) .. " bounds over to you.")
            self.room:send_except(actor, tostring(self.name) .. " runs over to " .. tostring(actor.name) .. ".")
            wait(1)
            local final_item = actor:get_quest_var("major_globe_spell:final_item")
            -- final_item is a quest var holding an object's local id within zone 534
            local item_name = objects.template(534, final_item).name
            actor:send(tostring(self.name) .. " says, 'Do you have " .. tostring(item_name) .. " to channel the power?  Please say you do!'")
        else
            actor:send(tostring(self.name) .. " turns his head to look at you.")
            self.room:send_except(actor, tostring(self.name) .. " turns his head to look at " .. tostring(actor.name) .. ".")
            self:command("cough")
            wait(2)
            actor:send(tostring(self.name) .. " says, 'You're a " .. tostring(actor.class) .. "!  Perhaps you can <b:cyan>assist</> me.'")
        end
    end
end$trig$, '53fd5557af00ce0e744ed9ea3ef54194'),
  -- data/triggers/534/534_51_major_globe_speech_assist.lua
  (534, 51, $trig$-- Converted from DG Script #53451: major_globe_speech_assist
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: assist assist? help help?
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "assist") or string.find(string.lower(speech), "assist?") or string.find(string.lower(speech), "help") or string.find(string.lower(speech), "help?")) then
    return true  -- No matching keywords
end
if (actor.is_player) and (actor.class == "sorcerer" or actor.class == "cryomancer" or actor.class== "pyromancer") and (actor.level >= 57) and not (actor:get_has_completed("major_globe_spell")) and (actor:get_quest_stage("major_globe_spell") == 0) then
    actor:start_quest("major_globe_spell")
    wait(0.2)
    self:emote("nods slowly.")
    wait(1)
    actor:send(tostring(self.name) .. " says, 'Yes...  I was recently defeated by a rogue demon roving this valley.  He injured me terribly, but...'")
    self:emote("breaks into a coughing fit!")
    wait(2)
    self:emote("recomposes himself.")
    actor:send(tostring(self.name) .. " says, 'I can't let down Ysgarran, though.  I must defeat the demon.'")
    wait(0.3)
    actor:send(tostring(self.name) .. " says, 'But not in this state.'")
    self:command("sigh")
    wait(3)
    actor:send(tostring(self.name) .. " says, 'Earle of the druids owes me a favor.  Please visit him in my behalf and acquire a salve for my wounds.'")
    wait(1)
    actor:send(tostring(self.name) .. " says, 'Tell him <b:cyan>\"Lirne sends me.\"</>  I'm sure he will help.'")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'You can check your <b:cyan>[spell progress]</> with me if you forget what to do.'")
end$trig$, '8ba65dfc97c2252d4679bbdd076940f2'),
  -- data/triggers/534/534_52_major_globe_speech_lirne_sends_me.lua
  (534, 52, $trig$-- Converted from DG Script #53452: major_globe_speech_lirne_sends_me
-- Original: MOB trigger, flags: GLOBAL, SPEECH, probability: 0%
-- NOTE: legacy probability 0% on SPEECH triggers means "always run on keyword
-- match" (the % is ignored for SPEECH); the converter's percent_chance(0)
-- gate would have made the script unreachable, so it has been removed.

-- Speech keywords: Lirne sends me
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "lirne") or string.find(string.lower(speech), "sends") or string.find(string.lower(speech), "me")) then
    return true  -- No matching keywords
end
wait(0.1)
if actor:get_quest_stage("major_globe_spell") == 1 then
    actor:advance_quest("major_globe_spell")
    self:command("smirk")
    actor:send(tostring(self.name) .. " says, 'Ah yes, Lirne.  He never writes and only drops by when he's injured.'")
    wait(3)
    actor:send(tostring(self.name) .. " says, 'Well, what got him this time?  Lions?  Tigers?  Be- ah, it doesn't matter.'")
    self:command("sigh")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'I will prepare an all-purpose healing salve for him.  But you will need to retrieve the components for me.'")
    self:command("ponder")
    wait(3)
    actor:send(tostring(self.name) .. " says, 'First, I will need some <b:yellow>shale</> to create a base.  You can probably find some on the nearby volcanic island.'")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'Return to me when you have procured the shale.'")
elseif actor:get_quest_stage("major_globe_spell") == 2 then
    actor:send(tostring(self.name) .. " says, 'Well yes, I already know that.  Did you get the shale yet?'")
elseif actor:get_quest_stage("major_globe_spell") > 0 then
    actor:send(tostring(self.name) .. " says, 'Yes, yes, I know!  You told me already!'")
else
    self:command("smirk")
    actor:send(tostring(self.name) .. " says, 'I doubt it.'")
end$trig$, 'd67a2952eb5fe25b3622d85c05a2e6ee'),
  -- data/triggers/534/534_54_lirne_refuse.lua
  (534, 54, $trig$-- Converted from DG Script #53454: Lirne Refuse
-- Original: MOB trigger, flags: RECEIVE, probability: 0%
-- NOTE: legacy probability 0% on RECEIVE means "always run", not "never";
-- the converter's percent_chance(0) gate has been removed.

-- Lirne refuses any item handed to him that isn't the right ingredient for
-- his current quest stage. The salve/sake/marigold quest items belong with
-- Earle, not Lirne, so they get a redirect message; everything else gets a
-- generic "no thanks".
local stage = actor:get_quest_stage("major_globe_spell")
-- TODO(parity): legacy DG checked object vnums 53451 (shale, zone 534/id 51),
-- 58002 (sake, zone 580/id 2), 58609 (marigold poultice, zone 586/id 9). The
-- converter incorrectly nested stage==3 / stage==4 inside the stage==2 branch
-- and lost the redirect message for stages 3 and 4. Reconstructed below using
-- composite (zone_id, local_id) checks; verify zone numbers against the
-- canonical ingredient definitions.
local response = "No thanks."
if stage == 2 then
    if object.zone_id == 534 and object.local_id == 51 then
        response = "Give this to Earle, not me."
    end
elseif stage == 3 then
    if object.zone_id == 580 and object.local_id == 2 then
        response = "Give this to Earle, not me."
    end
elseif stage == 4 then
    if object.zone_id == 586 and object.local_id == 9 then
        response = "Give this to Earle, not me."
    end
end
self.room:send(tostring(self.name) .. " refuses " .. tostring(object.shortdesc) .. ".")
wait(0.2)
self:say(response)
return true$trig$, 'd3727eafbc829e166b478f228b56e5e9'),
  -- data/triggers/534/534_57_major_globe_elemental_greet.lua
  (534, 57, $trig$-- Converted from DG Script #53457: major_globe_elemental_greet
-- Original: MOB trigger, flags: GLOBAL, GREET_ALL, probability: 100%
--
-- When a questor with major_globe_spell stage 8 (or the relevant elemental
-- wand quest) approaches an elemental of the matching type, there's a 1-in-4
-- chance to spawn an elemental ward. After a non-load roll, lock out further
-- rolls for 2 minutes via globals.last_enter.

-- TODO(parity): mob ids below were legacy 5-digit vnums in the original DG
-- (e.g. 2328 = vnum 2328 plant elemental). Confirm they map to the same
-- composite (zone_id, local_id) values once mob proto migration finishes;
-- self.id alone may be ambiguous across zones.
local load_ward
local wand
if (self.zone_id == 23 and self.id == 28) then
    -- plant elemental
    load_ward = 53
    wand = actor:get_quest_stage("acid_wand")
elseif (self.zone_id == 28 and self.id == 6) or (self.zone_id == 28 and self.id == 7) then
    -- mist elemental
    load_ward = 54
    wand = actor:get_quest_stage("air_wand")
elseif (self.zone_id == 28 and self.id == 8) or (self.zone_id == 28 and self.id == 9) or (self.zone_id == 484 and self.id == 231) then
    -- water elemental
    load_ward = 55
elseif (self.zone_id == 52 and self.id == 12) or (self.zone_id == 125 and self.id == 23) or (self.zone_id == 484 and self.id == 100) or (self.zone_id == 484 and self.id == 111) or (self.zone_id == 484 and self.id == 112) then
    -- flame elemental
    load_ward = 56
    wand = actor:get_quest_stage("fire_wand")
elseif (self.zone_id == 533 and self.id == 12) or (self.zone_id == 533 and self.id == 13) or (self.zone_id == 484 and self.id == 230) or (self.zone_id == 484 and self.id == 232) then
    -- ice elemental
    load_ward = 57
    wand = actor:get_quest_stage("ice_wand")
end
if actor:get_quest_stage("major_globe_spell") == 8 or wand == 8 then
    local now = timestamp()
    -- Roll only if first encounter or 2+ game hours since last non-load roll.
    local do_load = 0
    if globals.last_enter then
        if now - globals.last_enter >= 2 then
            do_load = random(1, 4)
        end
    else
        do_load = random(1, 4)
    end
    if do_load == 1 then
        if load_ward then
            self.room:spawn_object(534, load_ward)
            if actor:get_quest_stage("major_globe_spell") == 8 then
                actor:set_quest_var("major_globe_spell", "ward_" .. tostring(load_ward), 1)
            end
            wait(0.1)
            actor:send("<blue>" .. tostring(self.name) .. " flares briefly as you approach.</>")
            self.room:send_except(actor, "<blue>" .. tostring(self.name) .. " flares briefly as " .. tostring(actor.name) .. " approaches.</>")
        end
    else
        -- Save time stamp so questor must wait 2 minutes for next roll.
        globals.last_enter = now
    end
end$trig$, '1754dcb3a8082a45e44a667c37c07992'),
