  -- data/triggers/583/583_75_kod_demisekeep_newbie_guard.lua
  (583, 75, $trig$-- Converted from DG Script #58375: KoD_demisekeep_newbie_guard
-- Original: MOB trigger, flags: COMMAND, probability: 100%
--
-- Block players under level 30 from heading east; usher mid-level players
-- (30-59) through with a warning; allow level 60+ to pass without comment.

if cmd ~= "east" then
    return true  -- Not our command
end
if not actor.is_player then
    return true
end
if actor.level < 30 then
    self:command("smile")
    self:whisper(actor.name, "I would not suggest going any further.")
    wait(0.1)
    self:command("grin " .. tostring(actor.name))
    self:whisper(actor.name, "It is fraught with danger above your abilities.")
    return false  -- Block the east movement
elseif actor.level < 60 then
    self:say("I will let you pass, but still be careful beyond this point.")
    self:emote("points east.")
    wait(0.5)
    actor:move("east")
    return false  -- We've already moved them; suppress the original command
end
return true  -- Level 60+: allow normal movement$trig$, 'd8fbf4441b5be2546691ac291252191b'),
  -- data/triggers/583/583_80_holy_burn_the_wicked.lua
  (583, 80, $trig$if actor.class == "paladin" then
    if actor.alignment < 750 then
        wait(0.2)
        self.room:send("The holy blade of Godly vigor dulls in appearance.")
        actor:send("You are no longer holy enough to use this sacred weapon, you can no longer wield it.")
        self.room:send_except(actor, tostring(actor.name) .. "'s blade grows dull, unglowing.")
        actor:command("remove vigor")
    else  -- alignment >= 750
        wait(0.2)
        self.room:send("The holy blade of Godly vigor glows with a soft, white light.")
        actor:send("Your eyes widen with awe and splendor as you hold the holy blade of Godly vigor.")
        self.room:send_except(actor, tostring(actor.name) .. " is surrounded by a holy glow.")
    end
else  -- Non-paladin wielder
    if actor.alignment < -350 then
        wait(0.2)
        self.room:send("The holy blade of Godly vigor glows violently!")
        actor:send("The pain in your body is excruciating, you feel death.")
        local var_dam = random(1, 50) + 1517
        self.room:send_except(actor, tostring(actor.name) .. " convulses and life drains from his body. (<yellow>" .. tostring(var_dam) .. "</>)")
        actor:damage(var_dam)  -- type: physical
        -- Note: original DG warned this oforce can syserror if damage kills the victim.
        actor:command("remove vigor")
    else  -- alignment >= -350
        wait(0.2)
        self.room:send("The holy blade of Godly vigor vibrates unsteadily.")
        actor:send("This blade clearly is not happy to be in your hands.  Take care.")
        self.room:send_except(actor, tostring(actor.name) .. "'s hands shake unsteadily as he holds the blade.")
        actor:command("remove vigor")
    end
end$trig$, '6226d50bdde53be7b7685207b4a71ff2'),
  -- data/triggers/584/584_01_princess_receive.lua
  (584, 1, $trig$-- Only react when the swan feathers are received.
if not (object.zone_id == 584 and object.local_id == 17) then
    return true
end

wait(0.1)
self.room:send(tostring(self.name) .. " sighs in great relief.")
wait(0.2)
self:say("Thank you from the bottom of my heart, kind adventurer.")
self:say("Your deeds shall not go unrewarded.")
wait(0.2)
self:destroy_item("feathers")
self.room:spawn_object(584, 1)
self:command("give feather " .. tostring(actor.name))

-- Credit every grouped player still in the room with the "feather" step;
-- fall back to crediting the lone actor if they are not in a group.
local size = actor.group_size or 0
if size > 0 then
    for i = 1, size do
        local person = actor.group_member[i]
        if person and person.room == self.room then
            if person:get_quest_stage("kod_quest") == 0 then
                person:start_quest("kod_quest")
            end
            person:set_quest_var("kod_quest", "feather", 1)
        end
    end
else
    if actor:get_quest_stage("kod_quest") == 0 then
        actor:start_quest("kod_quest")
    end
    actor:set_quest_var("kod_quest", "feather", 1)
end$trig$, '144ae6390b842ecb61a2488b9689023f'),
