end$trig$, '1b8dcbdac6eda57e4aba8439a87a5094'),
  -- data/triggers/586/586_05_dragons_health_myorrhed_status_checker.lua
  (586, 5, $trig$-- Speech keywords: progress, status
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "progress") or string.find(speech_lower, "status")) then
    return true  -- No matching keywords
end

local stage = actor:get_quest_stage("dragons_health")
wait(0.2)
if actor:get_has_completed("dragons_health") then
    self.room:send(tostring(self.name) .. " says, 'You have already kept vigil with me.")
    self.room:send("</>May the Song of the Dragons give you strength.'")
    return true
end

local dragon, treasure
if stage == 1 then
    dragon = "the blue dragon in the Tower in the Wastes"
    treasure = "its crystal"
elseif stage == 2 then
    dragon = "Tri-Aszp"
    treasure = "one of her scales"
elseif stage == 3 then
    dragon = "Thelriki and Jerajai"
    treasure = "the jewel in their hoard"
elseif stage == 4 then
    dragon = "Sagece"
    treasure = "her skins and shields"
elseif stage == 5 then
    local total = 10000000 - (actor:get_quest_var("dragons_health:hoard") or 0)
    local plat = total // 1000
    local gold = (total // 100) - (plat * 10)
    local silv = (total // 10) - (plat * 100) - (gold * 10)
    local copp = total - (plat * 1000) - (gold * 100) - (silv * 10)
    self.room:send(tostring(self.name) .. " says, 'The new hatchling's hoard needs enriching.")
    self.room:send("</>" .. tostring(plat) .. " platinum, " .. tostring(gold) .. " gold, " .. tostring(silv) .. " silver, " .. tostring(copp) .. " copper")
    self.room:send("</>more in treasure and coins ought to do it.'")
    return true
else
    self:say("Progress of what?  You're not keeping guard with me...")
    return true
end

if stage == 4 then
    self.room:send(tostring(self.name) .. " says, 'You are undertaking your hardest task:'")
else
    self.room:send(tostring(self.name) .. " says, 'You are trying to:'")
end
self.room:send("- kill " .. tostring(dragon) .. " and bring me " .. tostring(treasure) .. ".")

if stage == 3 then
    local thelriki = actor:get_quest_var("dragons_health:thelriki")
    local jerajai = actor:get_quest_var("dragons_health:jerajai")
    if thelriki or jerajai then
        self.room:send("You have slain:")
        if thelriki then
            self.room:send("- Thelriki")
        end
        if jerajai then
            self.room:send("- Jerajai")
        end
    end
    self.room:send("You must still:")
    if not thelriki then
        self.room:send("- kill Thelriki")
    end
    if not jerajai then
        self.room:send("- kill Jerajai")
    end
    self.room:send("- bring the heartstone")
elseif stage == 4 then
    local item1 = actor:get_quest_var("dragons_health:520_16")
    local item2 = actor:get_quest_var("dragons_health:520_17")
    local item3 = actor:get_quest_var("dragons_health:520_22")
    local item4 = actor:get_quest_var("dragons_health:520_23")
    local sagece = actor:get_quest_var("dragons_health:sagece")
    if item1 or item2 or item3 or item4 or sagece then
        self.room:send("You have already:")
        if sagece then
            self.room:send("- slain Sagece of Raymif")
        end
        if item1 then
            self.room:send("- brought Sagece's skin")
        end
        if item2 then
            self.room:send("- brought Sagece's shield")
        end
        if item3 then
            self.room:send("- brought the skin from Sagece's hoard")
        end
        if item4 then
            self.room:send("- brought the shield from Sagece's hoard")
        end
    end
    self.room:send("You must still:")
    if not sagece then
        self.room:send("- kill Sagece of Raymif")
    end
    if not item1 then
        self.room:send("- bring Sagece's skin")
    end
    if not item2 then
        self.room:send("- bring Sagece's shield")
    end
    if not item3 then
        self.room:send("- find the skin in Sagece's hoard")
    end
    if not item4 then
        self.room:send("- find the shield in Sagece's hoard")
    end
end$trig$, 'abd780b5522a71abfe482f354bd518e1'),
  -- data/triggers/590/590_00_build_mutter.lua
  (590, 0, $trig$-- Converted from DG Script #59000: build_mutter
-- Original: MOB trigger, flags: RANDOM, probability: 30%

-- 30% chance to trigger
if not percent_chance(30) then
    return true
end
local val = random(1, 10)
-- switch on val
do
    local _sw1 = string.lower(tostring(val or ""))
    local _run1 = false
    repeat
        if _run1 or tonumber(_sw1) == 1 or tonumber(_sw1) == 2 then
            _run1 = true
            self:say("Man, Rydack is a slave driver.")
        end
        if _run1 or tonumber(_sw1) == 3 or tonumber(_sw1) == 4 then
            _run1 = true
            self:emote("starts using OLC.")
            break
        end
        if _run1 or tonumber(_sw1) == 5 or tonumber(_sw1) == 6 then
            _run1 = true
            self:emote("looks at his watch.")
            break
        end
        do  -- default
            _run1 = true
            self:emote("looks around to see if anyone is watching.")
        end
    until true
end$trig$, '04210336188179deadf4f626c01070fb'),
  -- data/triggers/590/590_01_mask_enmity_wear.lua
  (590, 1, $trig$-- Converted from DG Script #59001: mask_enmity_wear
-- Original: OBJECT trigger, flags: WEAR, probability: 100%
local _return_value = true  -- Default: allow action
if actor.is_player then
    if actor.alignment > -350 then
        _return_value = true
        wait(0.1)
        self.room:send("The mask of enmity starts to &9<blue>smoke</> violently!")
        wait(0.2)
        actor:send("You feel the smoke dig into your skin and burn!")
        self.room:send_except(actor, "The smoke from the mask digs into " .. tostring(actor.name) .. "'s skin and severely burns " .. tostring(actor.object) .. ".")
