  -- data/triggers/615/615_55_creeping_doom_logging_camp_drop.lua
  (615, 55, $trig$-- Converted from DG Script #61555: creeping_doom_logging_camp_drop
-- Original: WORLD trigger, flags: DROP, probability: 100%
if object.zone_id == 615 and object.local_id == 18 then
    wait(0.1)
    world.destroy(object)
    if actor:get_quest_stage("creeping_doom") == 4 then
        actor:advance_quest("creeping_doom")
    end
    self.room:send("&9<blue>The " .. tostring(objects.template(615, 18).name) .. " bursts open in a flood of insects!</>")
    wait(0.2)
    zone.echo(87, "<blue>&9An endless wave of crawling </><red>arachnoids<blue>&9 and </><green>insects<blue>&9 pours through the camp consuming everything in sight!</>")
    wait(1)
    zone.echo(87, "<blue>&9Screams pierce the quiet of the camp as everything is swallowed by a blanket of death!</>")

    -- Spared NPCs in the camp (zone 87 mob locals).
    local spare = { [8] = true, [10] = true, [11] = true, [14] = true }
    for local_id = 3, 59 do
        local r = get_room(87, local_id)
        if r and r.actors then
            for _, person in ipairs(r.actors) do
                if person.is_npc and not spare[person.local_id] then
                    r:at(function()
                        person:damage(5000)
                        r:send("<blue>&9An endless wave of crawling </><red>arachnoids<blue>&9 and </><green>insects<blue>&9 consumes " .. tostring(person.name) .. "!</>")
                    end)
                    zone.echo(87, "Someone screams as he is consumed by an endless wave of crawling <red>arachnoids</> and <green>insects</>!")
                end
            end
        end
        wait(0.2)
    end
    zone.echo(87, "<blue>&9Eerie silence falls over the camp as the deluge of death subsides...</>")
end$trig$, 'c56036fdbbcc2d5005eb1d1c4680440e'),
  -- data/triggers/615/615_56_creeping_doom_status_checker.lua
  (615, 56, $trig$-- Converted from DG Script #61556: creeping_doom_status_checker
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: progress status
local speech_lower = string.lower(speech)
if not (string.find(speech_lower, "progress") or string.find(speech_lower, "status")) then
    return true  -- No matching keywords
end
local stage = actor:get_quest_stage("creeping_doom")
wait(0.2)

local item1, item2, item3
local place1, place2, place3
local step

do
    local _sw1 = string.lower(tostring(stage or ""))
    if tonumber(_sw1) == 1 then
        item1 = { z = 118, l = 12 }
        place1 = "an assassin vine on Mist Mountain"
        item2 = { z = 162, l = 13 }
        place2 = "the great pyramid"
        item3 = { z = 480, l = 29 }
        place3 = "Rhalean's evil sister in the northern barrow"
        step = "gathering Nature's Rage"
    elseif tonumber(_sw1) == 2 then
        local essence = actor:get_quest_var("creeping_doom:spiders") or 0
        local total = 11 - essence
        self.room:send(tostring(self.name) .. " says, 'You are collecting essences of swarms from:")
        self.room:send("</>Flies, insects, spiders, bugs, scorpions, giant ant people, etc.'")
        self.room:send("You have found " .. tostring(essence) .. " essences.")
        self.room:send("You need to find " .. tostring(total) .. " more.")
        self.room:send("Remember, the tougher the bug, the better your chances of finding essences.")
        return true
    elseif tonumber(_sw1) == 3 then
        step = "locate three sources of Nature's Vengeance."
        item1 = { z = 484, l = 16 }
        place1 = "the elder tremaen in the elemental Plane of Fire"
        item2 = { z = 520, l = 34 }
        place2 = "the burning tree in Templace"
        item3 = { z = 625, l = 3 }
        place3 = "the Treant in the eldest Rhell's forest"
    elseif tonumber(_sw1) == 4 then
        self.room:send(tostring(self.name) .. " says, 'Take the Essence of Nature's Vengeance and")
        self.room:send("</>drop it at the entrance to the logging camp.'")
